insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('furnace-out-in-cold-weather-first-steps-sheet', 'Furnace Out in Cold Weather First Steps Sheet', 'worksheet'::resource_kind, 'A first-hour sheet for a client whose heat has failed on a cold day and who freezes up instead of acting.', 'Use it to turn a household emergency into a short ordered list the client can work down without spiraling.', array['Adults']::text[], '15 minutes, then as needed', 'A broken furnace in November is a real problem and a common spiral starter: the client imagines frozen pipes, a huge bill and a ruined week before they have made a call. The sheet asks for the first three actions in order (thermostat and breaker, a call, a warm room), who in their life has a spare heater or a couch, and the number they will not call before morning. Keep the planning concrete and the catastrophe column short. Watch for the client who will not ask a neighbor for a space heater because asking feels like failing; that is often the real work.', '[{"id": "f0", "type": "textarea", "label": "What has actually happened so far, in plain facts (no predictions yet):"}, {"id": "f1", "type": "textarea", "label": "The first three things to check or do, in order:"}, {"id": "f2", "type": "textarea", "label": "Who I could call tonight for a space heater, a couch or advice, and what I would say:"}, {"id": "f3", "type": "textarea", "label": "The warmest room in the house and how I will make it warmer for tonight:"}, {"id": "f4", "type": "textarea", "label": "The worries that showed up while writing this, and which of them can wait until morning:"}, {"id": "f5", "type": "textarea", "label": "What I will do at 9 a.m. tomorrow, and the one call I will make first:"}]'::jsonb, array['planning', 'stress', 'problem solving']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('holiday-tips-for-service-workers-decision-sheet', 'Holiday Tips for Service Workers Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for the yearly question of who to tip or thank and how much, for a client who agonizes over it.', 'Use it to settle a small seasonal money decision in one sitting instead of letting guilt and comparison drag it out for weeks.', array['Adults']::text[], '20 minutes', 'Who to thank at year end, the mail carrier, the building staff, the hairdresser, the child''s teacher, is a small decision that a client prone to guilt and comparison can turn into a month of dread. The sheet lists the people, what the client can actually spare, what each relationship calls for, and a note or a plate of cookies as an alternative where money is tight. Ask the client to decide once and write the date they will hand things out. Watch for the client who tips to buy off guilt rather than to say thanks; the sheet asks what each gift is for.', '[{"id": "f0", "type": "textarea", "label": "The people I am wondering about thanking this year:"}, {"id": "f1", "type": "textarea", "label": "What I can spare in total without regret in January:"}, {"id": "f2", "type": "textarea", "label": "For each person: what fits the relationship, in money, a note, food or a kind word:"}, {"id": "f3", "type": "textarea", "label": "The comparison thoughts that showed up (what others give, what I should give):"}, {"id": "f4", "type": "textarea", "label": "My decisions, written once, and the date I will hand them out:"}, {"id": "f5", "type": "textarea", "label": "After: how it felt to have it settled, and what I would change next year:"}]'::jsonb, array['money', 'decisions', 'guilt']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('passport-renewal-paperwork-pacing-sheet', 'Passport Renewal Paperwork Pacing Sheet', 'worksheet'::resource_kind, 'A paced plan for a multi-step government form the client has been avoiding, from photo to mailing.', 'Use it to break an avoided paperwork task into dated steps small enough to start today.', array['Adults', 'Teens']::text[], 'Three short sittings over a week', 'Renewing a passport, or any form with a photo, a fee, an old document and a trip to the post office, is a classic avoidance target: no step is hard, but together they feel like a wall. The sheet separates gathering, filling, photographing and mailing into their own short sittings on their own dates, and asks what the client will do when a step hits a snag (a missing document, a rejected photo). Watch for the client who insists on doing it all at once and then does none of it; the pacing is the point.', '[{"id": "f0", "type": "textarea", "label": "The task I have been putting off and roughly how long it has waited:"}, {"id": "f1", "type": "textarea", "label": "The pieces, broken into steps no longer than twenty minutes each:"}, {"id": "f2", "type": "textarea", "label": "The date and time for each step, written like an appointment:"}, {"id": "f3", "type": "textarea", "label": "What I will do if a step hits a snag, and who I can ask:"}, {"id": "f4", "type": "textarea", "label": "After each step: what I did, how long it actually took, and how I felt afterward:"}, {"id": "f5", "type": "textarea", "label": "What this taught me about the next form that lands on my desk:"}]'::jsonb, array['avoidance', 'planning', 'pacing']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('open-enrollment-benefits-choice-sheet', 'Open Enrollment Benefits Choice Sheet', 'worksheet'::resource_kind, 'A decision sheet for the yearly benefits window at work, for a client who clicks through in a panic or misses it.', 'Use it to give a client a calm order for a deadline-bound decision they tend to rush or avoid.', array['Adults']::text[], '30 minutes before the deadline', 'The benefits window arrives every fall with jargon, a deadline and real money attached, and clients handle it either by renewing last year''s choices without looking or by avoiding it until the last night. The sheet asks what changed this year in their life, which two or three questions actually matter to them, who they can ask, and a date well before the deadline. Keep it to the decisions that matter; the client does not need to understand every option. Watch for the client who treats choosing wrong as a moral failure rather than a correctable choice.', '[{"id": "f0", "type": "textarea", "label": "The deadline, and the date I will actually sit down with this (at least three days before):"}, {"id": "f1", "type": "textarea", "label": "What changed in my life this year that might change what I need:"}, {"id": "f2", "type": "textarea", "label": "The two or three questions that matter most to me about these choices:"}, {"id": "f3", "type": "textarea", "label": "Who I can ask at work or at home, and what I will ask them:"}, {"id": "f4", "type": "textarea", "label": "The choices I made, and why each one, in one line:"}, {"id": "f5", "type": "textarea", "label": "The worry about choosing wrong, and what I would do if I had to fix it next year:"}]'::jsonb, array['decisions', 'work', 'money']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('vet-bill-versus-pet-comfort-decision-sheet', 'Vet Bill Versus Pet Comfort Decision Sheet', 'worksheet'::resource_kind, 'A values and facts sheet for a hard decision about an aging or sick pet''s care, written in the clinician''s room.', 'Use it to hold the money, the love and the guilt of a pet care decision on one page so the client can decide and live with it.', array['Adults']::text[], 'Full session', 'Few decisions carry more quiet guilt than how far to go for a pet. The client is often weighing an estimate they cannot afford against a fear of being the person who gave up. The sheet asks for the facts the veterinarian gave, the animal''s comfort day to day, what the client can afford without harm to the household, and what the pet would want if it could say. Complete it in session; the client should not do this alone at the kitchen table. Watch for the belief that love is measured in dollars; ask what else love has looked like in this animal''s life.', '[{"id": "f0", "type": "textarea", "label": "What the veterinarian actually said about options, comfort and time, in plain words:"}, {"id": "f1", "type": "textarea", "label": "What my pet''s ordinary day looks like right now: eating, moving, resting, greeting me:"}, {"id": "f2", "type": "textarea", "label": "What I can spend without harming the household, and what the harm would be past that:"}, {"id": "f3", "type": "textarea", "label": "The guilt thought in its exact words:"}, {"id": "f4", "type": "textarea", "label": "What loving this animal has looked like over the years, apart from money:"}, {"id": "f5", "type": "textarea", "label": "The decision I am leaning toward, and what I would need to feel I chose with care:"}]'::jsonb, array['decisions', 'grief and loss', 'money']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('doctor-running-forty-minutes-late-personalization-sheet', 'Doctor Running Forty Minutes Late Personalization Sheet', 'cbt'::resource_kind, 'A thought record for the waiting room, where a delayed appointment turns into evidence that the client does not matter.', 'Use it to catch personalization in a situation that has nothing to do with the client and to practice a fairer read.', array['Adults', 'Teens']::text[], '15 minutes, in the waiting room', 'A long wait at the doctor is fertile ground for personalization: they forgot me, my time is worth less, they would not do this to someone important. The sheet asks the client to write the hot thought, list the explanations that have nothing to do with them (an emergency, a late start, a double booking), rate how much each explains the delay, and notice what their body does while they wait. Watch for the client who leaves rather than wait and then reads leaving as proof of the thought.', '[{"id": "f0", "type": "textarea", "label": "How long I have been waiting and what I was told:"}, {"id": "f1", "type": "textarea", "label": "The thought that showed up about why, in its exact words:"}, {"id": "f2", "type": "textarea", "label": "Explanations for the delay that have nothing to do with me (list at least four):"}, {"id": "f3", "type": "textarea", "label": "How much of the delay each explanation could account for, roughly:"}, {"id": "f4", "type": "textarea", "label": "What my body did while I waited, and what I did with the time:"}, {"id": "f5", "type": "textarea", "label": "A fairer sentence about the wait that I could believe at least halfway:"}]'::jsonb, array['thinking traps', 'personalization', 'core CBT']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('autocorrect-sent-the-wrong-word-catastrophe-sheet', 'Autocorrect Sent the Wrong Word Catastrophe Sheet', 'cbt'::resource_kind, 'A catastrophe ladder for a message that went out with a wrong or embarrassing word in it.', 'Use it to walk a client from the worst imagined fallout of a typo down to the likely outcome and a simple fix.', array['Adults', 'Teens']::text[], '10 minutes', 'A phone changed a word, the message is sent, and the client is already imagining the recipient''s contempt or a job in danger. The sheet runs the ladder: the worst case, how likely it really is, what the client would do if it happened, the most likely case, and the plain fix available right now (a one-line correction, or nothing). Most clients find the fix takes ten seconds and the dread took an hour. Watch for the client who deletes the message and avoids the person, which keeps the catastrophe alive.', '[{"id": "f0", "type": "textarea", "label": "What I meant to send, and what actually went out:"}, {"id": "f1", "type": "textarea", "label": "The worst thing I imagine happening because of it:"}, {"id": "f2", "type": "textarea", "label": "How likely that is, out of a hundred, and how I would cope if it did happen:"}, {"id": "f3", "type": "textarea", "label": "The most likely thing that happens (think of the last time someone sent me a typo):"}, {"id": "f4", "type": "textarea", "label": "The simple fix available right now, if any, and whether it is worth doing:"}, {"id": "f5", "type": "textarea", "label": "How long I spent dreading this, and what I would tell a friend who did the same:"}]'::jsonb, array['catastrophizing', 'decatastrophizing', 'communication']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('order-something-not-on-the-menu-experiment-sheet', 'Order Something Not on the Menu Experiment Sheet', 'cbt'::resource_kind, 'A behavioral experiment in which the client asks a server for a small change to a dish and records what happens.', 'Use it to test the prediction that asking for anything unusual earns annoyance, in a low-stakes everyday setting.', array['Adults', 'Teens']::text[], 'One meal out, plus 10 minutes after', 'Asking for the sauce on the side or a swap not listed on the menu is a tiny request that a client who fears being a bother will not make. The sheet has them write the prediction (the server will sigh, roll their eyes, say no), rate their belief in it, make one small request at one meal, and record what the server actually did and how long the discomfort lasted. Keep the request ordinary and polite. Watch for the client who apologizes three times while asking; that is a second experiment for another day.', '[{"id": "f0", "type": "textarea", "label": "The small request I will make, and where:"}, {"id": "f1", "type": "textarea", "label": "What I predict the server will do or think, and how sure I am (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "How uncomfortable I predict I will feel, and for how long:"}, {"id": "f3", "type": "textarea", "label": "What actually happened, in plain description:"}, {"id": "f4", "type": "textarea", "label": "How uncomfortable I actually felt, and when it faded:"}, {"id": "f5", "type": "textarea", "label": "What this tells me about asking for small things, and the next request I could try:"}]'::jsonb, array['behavioral experiment', 'predictions', 'assertiveness']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('copied-on-an-email-thread-mind-reading-sheet', 'Copied on an Email Thread Mind Reading Sheet', 'cbt'::resource_kind, 'A thought record for being added to an email thread late and reading the worst into why.', 'Use it to separate what the client knows about a workplace email from what they are inferring about intent.', array['Adults']::text[], '15 minutes', 'Being copied on a thread with no explanation sets off a particular kind of mind reading: they are building a case, they want me to see this, I am being set up. The sheet asks for the facts (who sent it, what it says, what was asked of the client), the inference, and three ordinary reasons someone adds a colleague to a thread. Then it asks what one neutral question would clear it up. Watch for the client who drafts a defensive reply before asking anything.', '[{"id": "f0", "type": "textarea", "label": "The email: who added me, what it actually says, and what, if anything, it asks of me:"}, {"id": "f1", "type": "textarea", "label": "What I decided it meant about me, in its exact words:"}, {"id": "f2", "type": "textarea", "label": "Three ordinary reasons someone adds a colleague to a thread:"}, {"id": "f3", "type": "textarea", "label": "What I actually know versus what I am guessing (two short lists):"}, {"id": "f4", "type": "textarea", "label": "One neutral question I could ask that would clear this up, and who I would ask:"}, {"id": "f5", "type": "textarea", "label": "The reply I was about to send, and the one I will send instead, if any:"}]'::jsonb, array['mind reading', 'work', 'thought record']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('bank-fraud-alert-text-catastrophe-ladder-sheet', 'Bank Fraud Alert Text Catastrophe Ladder Sheet', 'cbt'::resource_kind, 'A decatastrophizing sheet for the jolt of a fraud alert or an unexpected charge on the account.', 'Use it to give a client a steady order of checks before the alert becomes a ruined night.', array['Adults']::text[], '15 minutes', 'A fraud alert text, real or a scam itself, drops a client straight into worst case: emptied accounts, identity stolen, months of calls. The sheet asks for the facts on the screen, the worst case and its odds, the one safe action (call the number on the back of the card, never the one in the text), and what the client will do while waiting on hold. It also asks what the ruined-night version costs compared with the fifteen-minute version. Watch for the client who checks the balance twenty times rather than making the one call.', '[{"id": "f0", "type": "textarea", "label": "What the alert or charge actually says, copied exactly:"}, {"id": "f1", "type": "textarea", "label": "The worst thing I imagine, and how likely it really is:"}, {"id": "f2", "type": "textarea", "label": "The one safe action I can take now, and the number I will use (from the card, not the text):"}, {"id": "f3", "type": "textarea", "label": "What I will do with my hands and attention while on hold:"}, {"id": "f4", "type": "textarea", "label": "What the ruined-night version would cost me, compared with the fifteen-minute version:"}, {"id": "f5", "type": "textarea", "label": "After: what turned out to be true, and how long the fear lasted:"}]'::jsonb, array['catastrophizing', 'money', 'problem solving']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('mind-as-a-gps-recalculating-after-every-turn-page', 'Mind as a GPS Recalculating After Every Turn Page', 'act'::resource_kind, 'A defusion metaphor for a mind that announces a new route, warning or wrong turn every few seconds.', 'Use it to help a client hear the mind''s constant rerouting as a voice in the car, not the driver.', array['Adults', 'Teens']::text[], '20 minutes', 'Clients recognize the GPS at once: it never stops talking, it panics at every missed turn, and it has no idea where you actually want to go. The page invites the client to notice the mind recalculating (you should have, now you have to, turn back), name it as the GPS voice, and ask who is holding the wheel. The point is not to switch it off but to keep driving toward the chosen destination while it talks. Watch for the client who argues with the GPS; arguing is still following it.', '[{"id": "f0", "type": "textarea", "label": "Three things my mind said today that sounded like a GPS recalculating:"}, {"id": "f1", "type": "textarea", "label": "What happens when I obey every announcement, and what happens when I argue with it:"}, {"id": "f2", "type": "textarea", "label": "The destination I actually chose, in my own words (a value, not a to-do):"}, {"id": "f3", "type": "textarea", "label": "A sentence I can say when the voice starts up: ''There goes the GPS again, and I am still heading toward...'':"}, {"id": "f4", "type": "textarea", "label": "One moment this week I noticed the voice and kept driving anyway, and how that went:"}]'::jsonb, array['defusion', 'metaphor', 'core ACT']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('values-while-shoveling-the-neighbor-s-walk-page', 'Values While Shoveling the Neighbor''s Walk Page', 'act'::resource_kind, 'A committed action page for small unasked acts of care in a season that invites staying inside.', 'Use it to connect a value the client names to one concrete act in the coming week, done without waiting to feel like it.', array['Adults', 'Teens']::text[], '15 minutes, then one act this week', 'Cold months shrink the world, and a client who values being a good neighbor or a generous person can go all winter without doing anything that looks like it. The page starts with the value in the client''s words, asks for one small physical act in the next week (shoveling a walk, carrying a bag, dropping off soup) and what the mind will say to talk them out of it. Then it asks them to do it anyway and write what showed up. Watch for the client who turns the act into a test of whether they are good enough; the act is the value in motion, not a grade.', '[{"id": "f0", "type": "textarea", "label": "A value about how I want to be with the people around me, in my own words:"}, {"id": "f1", "type": "textarea", "label": "One small act this week that would be that value in motion (where, when, for whom):"}, {"id": "f2", "type": "textarea", "label": "What my mind will say to talk me out of it, word for word:"}, {"id": "f3", "type": "textarea", "label": "What I will do with those thoughts while I put my coat on anyway:"}, {"id": "f4", "type": "textarea", "label": "After: what I did, what showed up in me during and after, and whether I want more of it:"}]'::jsonb, array['values', 'committed action', 'connection']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('thoughts-as-a-screensaver-drifting-across-the-mind-page', 'Thoughts as a Screensaver Drifting Across the Mind Page', 'act'::resource_kind, 'A defusion page that treats repetitive thoughts as a screensaver: always moving, never the real work.', 'Use it to help a client watch familiar looping thoughts without taking them as a task to be solved.', array['Adults', 'Teens']::text[], '15 minutes', 'Some thoughts repeat so often they are more pattern than message: the same worry, the same replay, drifting across the mind whenever it goes idle. The page asks the client to name their screensavers, notice when they appear (usually in the quiet minutes), and practice watching them drift without clicking on them. Then it asks what they want to turn their attention to instead. Watch for the client who tries to delete the screensaver; the practice is noticing it is a screensaver and moving the mouse.', '[{"id": "f0", "type": "textarea", "label": "The thoughts that drift across my mind whenever it goes idle (my screensavers):"}, {"id": "f1", "type": "textarea", "label": "When they usually appear: the quiet minutes, the commute, bed:"}, {"id": "f2", "type": "textarea", "label": "What happens when I click on one and treat it as urgent work:"}, {"id": "f3", "type": "textarea", "label": "A practice sentence: ''There is the screensaver again,'' and what I will turn my attention to instead:"}, {"id": "f4", "type": "textarea", "label": "One quiet moment this week I watched it drift and did something I chose, and how it felt:"}]'::jsonb, array['defusion', 'automatic thoughts', 'metaphor']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('willing-to-hand-off-the-project-i-would-do-better-page', 'Willing to Hand Off the Project I Would Do Better Page', 'act'::resource_kind, 'A willingness page for delegating or sharing work while the mind insists only the client can do it right.', 'Use it to help a client hand off a task in the service of a value, carrying the discomfort of imperfect results.', array['Adults']::text[], '20 minutes, then one handoff', 'Many overloaded clients know they should delegate and never do, because watching someone do it differently is more uncomfortable than doing it all. The page asks for the task, the value served by handing it off (rest, trust, a colleague''s growth, time with family), the exact discomfort that will show up, and whether the client is willing to have that discomfort for that value. Then one real handoff this week. Watch for the client who hands it off and then redoes it at night; that is the move to notice.', '[{"id": "f0", "type": "textarea", "label": "The task I keep because I would do it better, and what keeping it costs me:"}, {"id": "f1", "type": "textarea", "label": "The value served by handing it off, in my words:"}, {"id": "f2", "type": "textarea", "label": "The discomfort that will show up when I watch it done differently, named as a feeling in the body:"}, {"id": "f3", "type": "textarea", "label": "Am I willing to have that discomfort in exchange for that value? What would willing look like in my behavior?"}, {"id": "f4", "type": "textarea", "label": "The handoff I will make this week: what, to whom, and the words I will use:"}, {"id": "f5", "type": "textarea", "label": "After: what I did when the urge to take it back arrived, and what happened:"}]'::jsonb, array['willingness', 'work', 'committed action']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('hourglass-sand-present-moment-page', 'Hourglass Sand Present Moment Page', 'act'::resource_kind, 'A present-moment practice built on watching sand fall, for a client who lives in the next hour.', 'Use it to give a client a three-minute anchor they can do with a kitchen timer or a phone video of falling sand.', array['Adults', 'Teens']::text[], 'Three minutes daily for two weeks', 'An hourglass gives the mind something slow and continuous to rest on, and the falling grains make a plain point: this is the only moment that is actually happening. The page asks the client to watch sand fall (a real timer, or a video) for three minutes, notice each time attention jumps ahead or back, and bring it to the grains again. Then they write what the mind did. Watch for the client who scores the practice; the jumps are the practice, not failures of it.', '[{"id": "f0", "type": "textarea", "label": "Where and when I will watch the sand each day, and what I will use:"}, {"id": "f1", "type": "textarea", "label": "Day one: where my attention went, and how many times I noticed and came back (a rough count is fine):"}, {"id": "f2", "type": "textarea", "label": "The future or past the mind kept pulling toward:"}, {"id": "f3", "type": "textarea", "label": "Day seven: what has changed in how quickly I notice the jump:"}, {"id": "f4", "type": "textarea", "label": "One moment outside the practice this week when I used ''this grain, now'' to land:"}]'::jsonb, array['present moment', 'mindfulness', 'core ACT']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('check-the-facts-when-the-doctor-orders-more-tests-card', 'Check the Facts When the Doctor Orders More Tests Card', 'dbt'::resource_kind, 'A check-the-facts card for the fear that follows a doctor asking for another scan, draw or follow-up.', 'Use it to separate what the doctor said from the story the client''s emotion built around it.', array['Adults']::text[], '15 minutes', 'Being sent for more tests is one of the most common triggers of an emotion that outruns the facts. The card walks the skill: the prompting event in plain words, the interpretation (they found something, they are not telling me), the emotion and its intensity, the facts that fit and do not fit the interpretation, and whether the emotion fits the facts. If it does, the card points to problem solving (write the questions for the next visit); if it does not, to opposite action for the wait. Watch for the client who reads ''to be safe'' as ''they know something.''', '[{"id": "f0", "type": "textarea", "label": "What the doctor actually said, as close to word for word as I can:"}, {"id": "f1", "type": "textarea", "label": "What I assumed it meant:"}, {"id": "f2", "type": "textarea", "label": "The emotion, and its intensity from 0 to 100:"}, {"id": "f3", "type": "textarea", "label": "Facts that fit my assumption, and facts that do not (two short lists):"}, {"id": "f4", "type": "textarea", "label": "Does the emotion fit the facts, or the assumption? What intensity would fit the facts?"}, {"id": "f5", "type": "textarea", "label": "If it fits: my questions for the next visit. If not: what I will do during the wait instead of searching:"}]'::jsonb, array['check the facts', 'health', 'core DBT']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('please-skills-for-the-shortest-days-of-the-year-card', 'PLEASE Skills for the Shortest Days of the Year Card', 'dbt'::resource_kind, 'A PLEASE skills card tuned to late fall: light, sleep, movement and food when the days are short and dark.', 'Use it to help a client reduce vulnerability to low mood in the darkest weeks with small physical routines.', array['Adults', 'Teens']::text[], 'Five minutes daily for the season', 'The PLEASE skills (treat physical illness, balance eating, avoid mood-altering substances, balance sleep, get exercise) matter most when the days shrink and a client''s routines drift. The card asks for one small adjustment in each area for the dark season: morning light within an hour of waking, a bedtime that does not slide with the early dark, a short walk at lunch when there is still daylight, a real meal rather than snacks in the dark. Keep each change tiny. Watch for the client who rebuilds all five at once and quits by the second week.', '[{"id": "f0", "type": "textarea", "label": "How my sleep, eating, movement and light have drifted since the days got short:"}, {"id": "f1", "type": "textarea", "label": "Light: when I will get outside or near a bright window in the morning, and for how long:"}, {"id": "f2", "type": "textarea", "label": "Sleep: the bedtime and wake time I will hold even when it is dark at five:"}, {"id": "f3", "type": "textarea", "label": "Movement: a short daylight walk or stretch, and the time of day I can protect for it:"}, {"id": "f4", "type": "textarea", "label": "Food and substances: one change that would steady me through the evenings:"}, {"id": "f5", "type": "textarea", "label": "End of week one: what I actually did, and what shifted in my mood or energy, if anything:"}]'::jsonb, array['PLEASE', 'emotion regulation', 'mood']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('turning-the-mind-after-the-promotion-went-elsewhere-card', 'Turning the Mind After the Promotion Went Elsewhere Card', 'dbt'::resource_kind, 'A turning-the-mind card for the days after a promotion or role went to someone else.', 'Use it to help a client choose acceptance of a workplace outcome again and again, as the resentment keeps returning.', array['Adults']::text[], '10 minutes daily for two weeks', 'Losing out on a promotion is a reality a client has to accept many times a day: in the meeting where the other person leads, in the hallway, in the paycheck. Turning the mind is noticing the moment of refusal (this is not fair, I will not accept this) and choosing, again, to turn toward what is. The card asks the client to log each turn: the trigger, the refusal thought, the inner turn, and what they did next. Acceptance here is not approval and does not rule out looking for another job. Watch for the client who confuses turning the mind with pretending to be fine.', '[{"id": "f0", "type": "textarea", "label": "What happened, in plain facts, and what I wanted to happen:"}, {"id": "f1", "type": "textarea", "label": "The refusal thoughts, in their exact words (''this should not have happened'', ''I cannot work here now''):"}, {"id": "f2", "type": "textarea", "label": "Each time I notice the refusal this week: the trigger, and the sentence I use to turn toward reality:"}, {"id": "f3", "type": "textarea", "label": "What I did right after each turn (kept working, took a breath, left the room):"}, {"id": "f4", "type": "textarea", "label": "What accepting this does not mean (list: approving, giving up, staying forever):"}, {"id": "f5", "type": "textarea", "label": "End of two weeks: how often I had to turn, and whether it got any easier to do:"}]'::jsonb, array['turning the mind', 'radical acceptance', 'work']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('dear-man-for-a-quieter-hotel-room-card', 'DEAR MAN for a Quieter Hotel Room Card', 'dbt'::resource_kind, 'A DEAR MAN script for asking a front desk to move a room, for a client who suffers through noise rather than ask.', 'Use it to rehearse a low-stakes request in a setting where the client''s comfort is a reasonable thing to ask for.', array['Adults']::text[], '15 minutes before a trip', 'A noisy hotel room next to the elevator is a near-perfect practice ground for DEAR MAN: a stranger, a reasonable request, and a client who would rather lose a night''s sleep than be a bother. The card walks Describe, Express, Assert, Reinforce, then Mindful, Appear confident, Negotiate, with the client writing each line in their own words for the front desk. Have them say it aloud in session. Watch for the client who leads with an apology or buries the ask in a story about how tired they are.', '[{"id": "f0", "type": "textarea", "label": "Describe: the facts about the room, in one or two neutral sentences:"}, {"id": "f1", "type": "textarea", "label": "Express: how it is affecting me, in one sentence that does not apologize:"}, {"id": "f2", "type": "textarea", "label": "Assert: the exact request (a different room, a different floor), said plainly:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what it would mean for my stay, said as a benefit to them too:"}, {"id": "f4", "type": "textarea", "label": "Mindful and Appear confident: what I will do if they say nothing is available, and how I will stand and speak:"}, {"id": "f5", "type": "textarea", "label": "Negotiate: what I would accept instead (earplugs and a late checkout, a partial refund, a move tomorrow):"}]'::jsonb, array['DEAR MAN', 'interpersonal effectiveness', 'travel']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('wise-mind-at-the-car-dealership-card', 'Wise Mind at the Car Dealership Card', 'dbt'::resource_kind, 'A wise mind card for a high-pressure purchase, where emotion mind wants the car and reasonable mind wants to flee.', 'Use it to give a client a pause practice they can take into a sales conversation and use before signing anything.', array['Adults']::text[], '20 minutes, then on the lot', 'A dealership is built to tip people into emotion mind: the new car smell, the shrinking offer, the salesperson''s urgency. Reasonable mind, in reaction, often refuses the whole thing. The card asks the client to write what emotion mind wants, what reasonable mind insists, and then to find the wise mind sentence that holds both (I want this and I will sleep on it). It includes a pause line the client can say out loud to the salesperson. Watch for the client who decides in advance that wise mind means saying no; sometimes it means buying the car tomorrow.', '[{"id": "f0", "type": "textarea", "label": "Emotion mind on the lot: what it wants, and what it says to get it:"}, {"id": "f1", "type": "textarea", "label": "Reasonable mind: what it insists on, and the tone it uses:"}, {"id": "f2", "type": "textarea", "label": "A wise mind sentence that holds both, written before I go:"}, {"id": "f3", "type": "textarea", "label": "The pause line I will say out loud when pressed (''I do not sign anything the same day''):"}, {"id": "f4", "type": "textarea", "label": "My walk-away number and the person I will call before deciding:"}, {"id": "f5", "type": "textarea", "label": "After: what I did, which mind was driving, and whether I am at peace with the result:"}]'::jsonb, array['wise mind', 'decisions', 'money']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('driving-directions-backseat-comments-pact-for-partners', 'Driving Directions Backseat Comments Pact for Partners', 'couples'::resource_kind, 'A pact for the car, where one partner drives and the other narrates every turn, speed and parking choice.', 'Use it to turn a recurring in-car fight into agreed roles each partner writes in their own words.', array['Couples']::text[], '20 minutes, then the next drive', 'The car is a tiny room with no exit, and commentary on the driving is a fight couples describe often and rarely fix. Each partner writes their part: the driver names what is actually helpful (a heads-up about an exit, nothing about speed) and what feels like contempt; the passenger names what they fear in silence and what they will do with their hands and attention instead of narrating. They agree one phrase that means ''please stop'' and one that means ''I actually need a heads-up.'' Watch for the pair where the commentary is about a past accident; that needs its own talk.', '[{"id": "f0", "type": "textarea", "label": "Driver: what comments actually help me, and which ones land as criticism:"}, {"id": "f1", "type": "textarea", "label": "Passenger: what I am afraid will happen if I stay quiet, and where that fear comes from:"}, {"id": "f2", "type": "textarea", "label": "Passenger: what I will do with my attention instead of narrating (navigation, music, the view):"}, {"id": "f3", "type": "textarea", "label": "Our agreed phrase for ''please stop,'' and our agreed phrase for ''I really need to say this'':"}, {"id": "f4", "type": "textarea", "label": "How we will handle it when one of us slips, without it becoming the fight:"}, {"id": "f5", "type": "textarea", "label": "After the next long drive: what we each noticed, and what we would keep:"}]'::jsonb, array['couples', 'communication', 'conflict']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('holiday-decorating-timing-and-taste-pact-for-partners', 'Holiday Decorating Timing and Taste Pact for Partners', 'couples'::resource_kind, 'A pact for when the decorations go up, how many, and whose style wins, for partners who fight about it every year.', 'Use it to settle a seasonal tug of war with a shared plan each partner has a hand in.', array['Couples']::text[], '20 minutes before the season', 'One partner wants lights up the day after Thanksgiving and the other wants a bare house until mid-December, or one loves the tasteful few and the other the inflatable snowman. Underneath are histories: how each grew up, what the season meant, what a full or quiet house signaled. The pact asks each partner for their picture of the season and where it came from, then for a shared timeline and a split of spaces (the yard is yours, the mantel is mine). Watch for the pair where the fight is really about who does the work; add that to the plan.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my picture of the season at home, and where it came from in my history:"}, {"id": "f1", "type": "textarea", "label": "Partner B: my picture of the season at home, and where it came from in my history:"}, {"id": "f2", "type": "textarea", "label": "What each of us is really protecting (quiet, joy, memory, order, a childhood we did or did not have):"}, {"id": "f3", "type": "textarea", "label": "Our timeline: when things go up, when they come down, and who does the work for each part:"}, {"id": "f4", "type": "textarea", "label": "Spaces: which rooms or areas are each partner''s to decide, and which are shared:"}, {"id": "f5", "type": "textarea", "label": "One thing each of us will do this year that is purely for the other''s version of the season:"}]'::jsonb, array['couples', 'holidays', 'fairness']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('who-drives-on-the-long-holiday-trip-pact-for-partners', 'Who Drives on the Long Holiday Trip Pact for Partners', 'couples'::resource_kind, 'A planning pact for a long drive to family, covering who drives when, stops, music and the quiet hours.', 'Use it to get the arguments about the drive settled before the drive, so the arrival is not already sour.', array['Couples']::text[], '20 minutes the week before', 'A six-hour drive to a relative''s house often does more damage to a couple than the visit itself. The pact asks each partner what they need to arrive in decent shape (a stretch of silence, a particular stop, not being the one who drives through the city), splits the driving into legs, agrees on music and phone rules, and names what each will do when the other gets short. It also asks what they will say to each other in the driveway before going in. Watch for the pair who treat the drive as dead time; it can be the only hours alone they get that week.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need on a long drive to arrive in decent shape:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need on a long drive to arrive in decent shape:"}, {"id": "f2", "type": "textarea", "label": "The legs of the drive and who takes each, with the planned stops:"}, {"id": "f3", "type": "textarea", "label": "Music, podcasts, phones and quiet: our agreement, in a few lines:"}, {"id": "f4", "type": "textarea", "label": "What each of us will do when the other gets short, and the phrase that means ''I need ten quiet minutes'':"}, {"id": "f5", "type": "textarea", "label": "What we will say to each other in the driveway before we go in:"}]'::jsonb, array['couples', 'travel', 'planning']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('snow-shoveling-and-ice-melt-division-for-partners', 'Snow Shoveling and Ice Melt Division for Partners', 'couples'::resource_kind, 'A fair-division sheet for the winter chores that appear overnight and fall to whoever gets up first.', 'Use it to settle who clears what and when, so the morning after a storm does not start with resentment.', array['Couples']::text[], '15 minutes before the first snow', 'Snow chores are unplanned, physical and time-sensitive, which makes them a quiet source of scorekeeping all winter. The sheet asks each partner what they can and cannot do (a bad back, an early shift), lists the jobs (walk, steps, car, ice melt, the elderly neighbor''s path), and assigns them by day of the week or by who is home, with a backup when one is sick. It also asks what thanks looks like for a job done at six in the morning. Watch for the partner who does it all and then resents it; the sheet asks for the ask they never make.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I can do, what I cannot, and what I quietly resent about last winter:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can do, what I cannot, and what I quietly resent about last winter:"}, {"id": "f2", "type": "textarea", "label": "The jobs, listed: walk, steps, driveway, cars, ice melt, anything else:"}, {"id": "f3", "type": "textarea", "label": "Who does what, by weekday or by who is home, and the backup when one of us is sick:"}, {"id": "f4", "type": "textarea", "label": "Gear and supplies: what we need before the first storm and who buys it:"}, {"id": "f5", "type": "textarea", "label": "What thanks looks like for a job done in the dark before work:"}]'::jsonb, array['couples', 'fairness', 'household']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('tv-volume-and-subtitles-pact-for-partners', 'TV Volume and Subtitles Pact for Partners', 'couples'::resource_kind, 'A small-friction pact for the nightly fight over the remote: volume, subtitles, and who gets to pause.', 'Use it to resolve a recurring evening irritation with a few concrete rules both partners write.', array['Couples']::text[], '15 minutes', 'One partner needs the volume up or the subtitles on, the other finds both unbearable, and the evening together turns into sighing over the remote. Small, nightly and unresolved, it corrodes more than its size suggests. The pact asks each partner what they actually need to enjoy a show, what the other''s preference does to them, and then builds rules: subtitles on for shows with accents, a volume ceiling, headphones for late viewing, and who pauses when. Watch for the pair where one partner''s hearing has changed; name it kindly and plan for it.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need to actually enjoy watching something, and what the other''s way does to me:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need to actually enjoy watching something, and what the other''s way does to me:"}, {"id": "f2", "type": "textarea", "label": "Our rules: subtitles when, volume ceiling, headphones when, who holds the remote:"}, {"id": "f3", "type": "textarea", "label": "The pause rule: when either of us may pause, and how we ask:"}, {"id": "f4", "type": "textarea", "label": "What we will do the first night one of us breaks the pact:"}, {"id": "f5", "type": "textarea", "label": "After one week: what worked, and what we want to change:"}]'::jsonb, array['couples', 'household', 'communication']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('pinecone-prickly-side-soft-side-feelings-sort-play', 'Pinecone Prickly Side Soft Side Feelings Sort Play', 'kids'::resource_kind, 'A sorting play in which a child decides which feelings are prickly and which are soft, using pinecones and cotton.', 'Use it to give a young child a hands-on way to name uncomfortable and comfortable feelings and what each needs.', array['Children']::text[], '20 minutes', 'A pinecone and a handful of cotton balls give a child two textures to think with: prickly feelings and soft ones. The child names a feeling for each card the clinician holds up and places it on the prickly pile or the soft pile, then decides what a prickly feeling needs to get softer (a hug, a run, a drink of water, telling someone). The parent plays alongside, sorting their own feelings honestly, so the child sees that grown-ups have prickly ones too. Watch for the child who sorts every feeling as soft to please you; model a prickly one first.', '[{"id": "f0", "type": "textarea", "label": "Feelings I put on the prickly pile:"}, {"id": "f1", "type": "textarea", "label": "Feelings I put on the soft pile:"}, {"id": "f2", "type": "textarea", "label": "What a prickly feeling needs to get softer (draw or write):"}, {"id": "f3", "type": "textarea", "label": "A prickly feeling my grown-up shared, and what they do with it:"}, {"id": "f4", "type": "textarea", "label": "Where I will keep my pinecone to remind me:"}]'::jsonb, array['children', 'emotion identification', 'play']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('mitten-puppet-warm-words-play', 'Mitten Puppet Warm Words Play', 'kids'::resource_kind, 'A puppet play in which an old mitten becomes a character who only says warm words, for a child hard on themselves.', 'Use it to give a self-critical child a voice outside themselves that practices kind, specific self-talk.', array['Children']::text[], '25 minutes', 'An old mitten with button eyes becomes the Warm Words puppet, and the rule is that the puppet can only say kind, true things. The child decorates it, then the clinician plays out small moments (a spilled drink, a lost game, a wrong answer) and the child answers as the puppet. The parent takes a turn being the one who messed up so the child can practice warming them too. Send the mitten home for the parent to bring out at bedtime. Watch for the child who makes the puppet say kind things they obviously do not believe; slow down and ask for a smaller, truer one.', '[{"id": "f0", "type": "textarea", "label": "What my Warm Words mitten looks like (draw it):"}, {"id": "f1", "type": "textarea", "label": "Three warm, true things it said to me when I messed up in our play:"}, {"id": "f2", "type": "textarea", "label": "What it said to my grown-up when they messed up:"}, {"id": "f3", "type": "textarea", "label": "A time this week I could use the mitten voice:"}, {"id": "f4", "type": "textarea", "label": "Where the mitten lives at home and when my grown-up will bring it out:"}]'::jsonb, array['children', 'self-talk', 'play']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('ice-cube-tray-feelings-color-sort-play', 'Ice Cube Tray Feelings Color Sort Play', 'kids'::resource_kind, 'A sorting play using an ice cube tray and colored pom-poms to show how many of each feeling a day held.', 'Use it to help a child see a day as a mix of feelings instead of one bad one, with a parent sorting beside them.', array['Children']::text[], '15 minutes, repeated at bedtime', 'An empty ice cube tray and a bag of colored pom-poms make a feelings chart a young child can actually use. Each color is a feeling the child picks, and at bedtime they drop pom-poms into the tray for the feelings the day held, one for each time. A bad day usually turns out to have three yellows in it too. The parent fills a tray beside them and talks about one cube honestly. Watch for the child who only fills the angry color; ask about the morning, the bus, the snack, until a second color appears.', '[{"id": "f0", "type": "textarea", "label": "My colors and what feeling each one means:"}, {"id": "f1", "type": "textarea", "label": "Tonight''s tray: how many of each color, and what the biggest pile was about:"}, {"id": "f2", "type": "textarea", "label": "One pom-pom I almost forgot to add (a small good or funny moment):"}, {"id": "f3", "type": "textarea", "label": "What my grown-up put in their tray tonight:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about my days after a week of trays:"}]'::jsonb, array['children', 'emotion identification', 'play']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('paper-snowflake-cut-away-a-worry-craft', 'Paper Snowflake Cut Away a Worry Craft', 'kids'::resource_kind, 'A craft in which a child folds paper, writes worries on the folds, cuts them away and opens a snowflake.', 'Use it to let a child act out letting go of worries, with a parent making their own snowflake alongside.', array['Children']::text[], '20 minutes', 'The child folds a square of paper into a triangle, writes or draws small worries along the folded edges, and snips them away as the clinician names each one aloud. Opening the snowflake is the moment: what was a list of worries is now a pattern on the window. The parent makes one too and names at least one real grown-up worry they cut away, so the child sees it done. Keep scissors age-appropriate and the worries small; a big one gets talked about first. Watch for the child who wants to keep the cut pieces; that is fine, give them an envelope.', '[{"id": "f0", "type": "textarea", "label": "The worries I wrote on my folds:"}, {"id": "f1", "type": "textarea", "label": "How it felt to cut each one away:"}, {"id": "f2", "type": "textarea", "label": "What my snowflake looks like now (tape it here or draw it):"}, {"id": "f3", "type": "textarea", "label": "The worry my grown-up cut away from their snowflake:"}, {"id": "f4", "type": "textarea", "label": "Where we will hang the snowflakes:"}]'::jsonb, array['children', 'worry', 'craft']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('bubble-wrap-pop-one-at-a-time-patience-play', 'Bubble Wrap Pop One at a Time Patience Play', 'kids'::resource_kind, 'A patience play in which a child pops one bubble per slow breath instead of the whole sheet at once.', 'Use it to practice slowing down and waiting with a child who rushes, with the parent as the breath counter.', array['Children']::text[], '10 minutes', 'Bubble wrap begs to be popped all at once, which is exactly why it works for practicing patience. The rule is one pop per slow breath out, and the parent counts the breath while the child waits with a finger hovering. Ten pops done slowly, then a free-for-all as the reward. Talk afterward about what the waiting felt like in the body and where else that waiting could help (the line at school, a turn on the swing). Watch for the child who cannot wait past the third pop; shorten to five and build up.', '[{"id": "f0", "type": "textarea", "label": "How many slow pops I did before the free-for-all:"}, {"id": "f1", "type": "textarea", "label": "What the waiting felt like in my hands and tummy:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up did to help me wait:"}, {"id": "f3", "type": "textarea", "label": "A place at school or home where I could use a slow-pop breath:"}, {"id": "f4", "type": "textarea", "label": "How many I want to try next time:"}]'::jsonb, array['children', 'patience', 'play']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('group-juggle-name-toss-game', 'Group Juggle Name Toss Game', 'game'::resource_kind, 'A circle game in which the group tosses soft balls in a fixed order, calling names, adding balls until it breaks down.', 'Use it to warm up a group, learn names and practice staying calm and laughing when a shared system falls apart.', array['Groups', 'Teens']::text[], '15 minutes', 'Rules: the group stands in a circle. One soft ball is tossed to someone across the circle with their name called; they toss to someone new, until everyone has caught once and the ball returns to the start. Now repeat the exact same order, and add a second ball a few throws behind, then a third. It falls apart; that is the game. Debrief: what did your body do when the balls started dropping, who laughed, who froze, who blamed, and what helped the group recover. Watch for the member who leaves the circle when it gets chaotic; invite them to narrate instead.', '[{"id": "f0", "type": "textarea", "label": "How many balls we got to before it fell apart:"}, {"id": "f1", "type": "textarea", "label": "What my body did when the balls started dropping:"}, {"id": "f2", "type": "textarea", "label": "What I noticed myself doing: laughing, freezing, blaming, apologizing, fixing:"}, {"id": "f3", "type": "textarea", "label": "What helped the group recover and try again:"}, {"id": "f4", "type": "textarea", "label": "Where else in my week a shared system falls apart, and what I could borrow from this:"}]'::jsonb, array['group', 'game', 'stress']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('pass-the-face-expression-chain-game', 'Pass the Face Expression Chain Game', 'game'::resource_kind, 'A line game in which an expression is passed from face to face and the last player guesses the feeling.', 'Use it to practice reading and showing feelings and to show how a feeling changes as it passes between people.', array['Groups', 'Children', 'Teens']::text[], '15 minutes', 'Rules: the group stands in a line facing one way. The leader shows the first player a feeling card, the player makes the face and taps the next shoulder; that player turns, sees the face for three seconds, and passes it on. The last player guesses the feeling, then the line turns around to compare the first face with the last. Rotate who starts. Debrief: which feelings traveled well, which turned into something else, and what that says about how moods move through a family or a classroom. Watch for the player who exaggerates to get laughs; ask for the quiet version too.', '[{"id": "f0", "type": "textarea", "label": "The feelings we passed, and which ones made it to the end unchanged:"}, {"id": "f1", "type": "textarea", "label": "A feeling that turned into a different one along the line, and where it changed:"}, {"id": "f2", "type": "textarea", "label": "What it was like to make the face versus read the face:"}, {"id": "f3", "type": "textarea", "label": "A time a mood traveled through my house or class like this:"}, {"id": "f4", "type": "textarea", "label": "One feeling I find hard to show or read, and what I noticed about it today:"}]'::jsonb, array['group', 'emotion identification', 'game']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('spoon-and-marble-steady-walk-game', 'Spoon and Marble Steady Walk Game', 'game'::resource_kind, 'A relay in which players carry a marble on a spoon across the room, learning that rushing drops it.', 'Use it to make a point about pace and steadiness in a group that tends to rush, then talk about where that applies.', array['Groups', 'Children', 'Teens']::text[], '15 minutes', 'Rules: two teams, a spoon and a marble each. Players walk, not run, to a line and back, handing the spoon to the next player; a dropped marble means stopping, picking it up and starting that leg again. Round two: each player names one thing they do too fast in their week before they walk. Debrief: what made the marble fall, what the body did when it did, and what a steady pace felt like compared with a fast one. Watch for the player who gives up after one drop; the retry is the lesson, so cheer the pickup.', '[{"id": "f0", "type": "textarea", "label": "How many times my marble fell, and what I was doing each time:"}, {"id": "f1", "type": "textarea", "label": "What steady felt like in my feet and hands:"}, {"id": "f2", "type": "textarea", "label": "The thing I named that I do too fast in my week:"}, {"id": "f3", "type": "textarea", "label": "What my team did when someone dropped a marble:"}, {"id": "f4", "type": "textarea", "label": "One place I will try the spoon pace this week:"}]'::jsonb, array['group', 'game', 'regulation']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('silent-birthday-line-up-game', 'Silent Birthday Line Up Game', 'game'::resource_kind, 'A no-talking game in which the group lines up by birthday using only gestures, then debriefs how they did it.', 'Use it to build nonverbal communication and patience in a group and to notice who leads and who waits.', array['Groups', 'Teens']::text[], '15 minutes', 'Rules: no talking, no writing. The group must line up in order of birthday, January at one end and December at the other, using only gestures. When they think they are done, each person says their birthday aloud to check. Round two: by the number of letters in their first name, or by how far they traveled to get here. Debrief: who took charge, who waited to be placed, what gestures worked, how it felt not to be able to explain yourself. Watch for the member who stands still until moved; ask what that is like elsewhere.', '[{"id": "f0", "type": "textarea", "label": "How we did on the first try, and where the line was wrong:"}, {"id": "f1", "type": "textarea", "label": "What I did: led, waited, guessed, counted on fingers, something else:"}, {"id": "f2", "type": "textarea", "label": "The gesture that worked best for the group:"}, {"id": "f3", "type": "textarea", "label": "What it was like to not be able to explain myself with words:"}, {"id": "f4", "type": "textarea", "label": "Where in my life I wait to be placed rather than finding my spot, and one small change:"}]'::jsonb, array['group', 'communication', 'game']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('rock-paper-scissors-cheer-squad-tournament-game', 'Rock Paper Scissors Cheer Squad Tournament Game', 'game'::resource_kind, 'A tournament in which every player who loses becomes the winner''s cheer squad until one player has the whole room.', 'Use it to practice losing gracefully and cheering for others in a group, with a debrief on both feelings.', array['Groups', 'Children', 'Teens']::text[], '15 minutes', 'Rules: everyone pairs up and plays one round of rock paper scissors. The loser joins the winner''s squad and follows them cheering their name as they find a new opponent. Squads merge with each round until two players face off with the whole room split behind them. Debrief: what it felt like to lose and switch to cheering, what it felt like to be cheered, and whether the switch was hard. Watch for the player who sulks in the squad rather than cheering; ask what losing means to them, and play again.', '[{"id": "f0", "type": "textarea", "label": "How far I got before I lost, and what the losing moment felt like:"}, {"id": "f1", "type": "textarea", "label": "What it was like to switch from playing to cheering for someone else:"}, {"id": "f2", "type": "textarea", "label": "What it felt like to have a squad cheering my name, if I did:"}, {"id": "f3", "type": "textarea", "label": "What losing usually means to me, and whether today changed that at all:"}, {"id": "f4", "type": "textarea", "label": "One place this week I could be a cheer squad for someone who beat me at something:"}]'::jsonb, array['group', 'game', 'social skills']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('car-backfire-and-sudden-noise-recovery-steps-sheet', 'Car Backfire and Sudden Noise Recovery Steps Sheet', 'worksheet'::resource_kind, 'A stabilizing sheet for the minutes after a sudden loud noise sends a client''s body into alarm.', 'Use it to give a client a short rehearsed sequence for coming back after a startle, with no reliving required.', array['Adults', 'Teens']::text[], '15 minutes, then as needed', 'A backfire, a dropped tray or a slammed door can put a client with a trauma history into full alarm, and the shame about the reaction often lasts longer than the alarm. The sheet is for afterward: name what the body did without judging it, three things in the room that say now, a long exhale, one sentence to a companion if one is there, and what the client will do next. It never asks what the noise reminded them of. Rehearse it in session when calm. Watch for the client who apologizes for startling; the sheet includes a line that replaces the apology.', '[{"id": "f0", "type": "textarea", "label": "What my body does in the seconds after a sudden noise (plain description, no judgment):"}, {"id": "f1", "type": "textarea", "label": "Three things I can look for in any room that tell me what year and place this is:"}, {"id": "f2", "type": "textarea", "label": "The breath I will use: how long in, how long out, how many times:"}, {"id": "f3", "type": "textarea", "label": "One sentence I can say to someone with me (''Loud noise, give me a minute''), instead of an apology:"}, {"id": "f4", "type": "textarea", "label": "What I will do next, once my breath is back: keep walking, sit, sip water:"}, {"id": "f5", "type": "textarea", "label": "After a real startle: what I used from this, and how long it took to settle:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'stabilizing']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('needing-the-lights-on-means-i-am-childish-check-sheet', 'Needing the Lights On Means I Am Childish Check Sheet', 'cbt'::resource_kind, 'A thought check for the shame a client feels about sleeping with a light on or a door open after trauma.', 'Use it to examine the self-judgment attached to a safety habit without asking the client to drop the habit.', array['Adults', 'Teens']::text[], '15 minutes', 'Many clients with a trauma history sleep with a light on, the door open or the TV murmuring, and judge themselves for it harshly. The sheet leaves the habit alone and goes after the judgment: what the habit does for the client, what they would say to a friend who did the same, and what the word ''childish'' is covering (fear, grief, a wish to be past this). The clinician''s judgment about whether and when to change the habit comes later. Watch for the client who wants to stop the habit tonight to prove the thought wrong.', '[{"id": "f0", "type": "textarea", "label": "The habit, described plainly, and how long it has been with me:"}, {"id": "f1", "type": "textarea", "label": "The thought about myself for needing it, in its exact words:"}, {"id": "f2", "type": "textarea", "label": "What the habit actually does for me at night:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend who told me they did the same thing:"}, {"id": "f4", "type": "textarea", "label": "What the harsh word is covering: a feeling I would rather not name:"}, {"id": "f5", "type": "textarea", "label": "A sentence about the habit that is accurate and does not insult me:"}]'::jsonb, array['PTSD and trauma', 'self-criticism', 'thinking traps']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('nervous-system-as-a-night-watchman-due-for-relief-page', 'Nervous System as a Night Watchman Due for Relief Page', 'act'::resource_kind, 'An acceptance metaphor for a body that keeps watch all night because no one ever told it the shift was over.', 'Use it to help a client relate to hypervigilance with respect rather than hostility, and to practice offering relief.', array['Adults', 'Teens']::text[], '20 minutes', 'The night watchman did a real job once, and nobody came to relieve him, so he is still walking the halls. The page invites the client to see their alertness as a loyal worker rather than a defect, to notice when he is on duty (the scan of the restaurant, the waking at every sound), and to practice relieving him for short stretches: a sentence of thanks and a few minutes of chosen attention elsewhere. It never asks what he was watching for. Watch for the client who wants to fire the watchman; he does not leave when yelled at.', '[{"id": "f0", "type": "textarea", "label": "When my watchman is on duty: the places, times and sounds that put him on patrol:"}, {"id": "f1", "type": "textarea", "label": "What he has protected me from, and what the job costs me now:"}, {"id": "f2", "type": "textarea", "label": "A sentence of thanks I can say to him, in my own words:"}, {"id": "f3", "type": "textarea", "label": "What relieving him for five minutes would look like: where my attention would go instead:"}, {"id": "f4", "type": "textarea", "label": "One moment this week I gave him a short break, and what happened in my body:"}]'::jsonb, array['PTSD and trauma', 'acceptance', 'metaphor']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-a-hot-water-bottle-at-bedtime-card', 'Self-Soothe With a Hot Water Bottle at Bedtime Card', 'dbt'::resource_kind, 'A self-soothe card built around warmth and weight at bedtime, for a body that braces at night.', 'Use it to give a client one simple sensory routine that signals safety to the body before sleep.', array['Adults', 'Teens']::text[], 'Ten minutes nightly', 'Warmth on the belly or the back of the neck tells the body something words cannot, and a hot water bottle is cheap, quiet and available in any home. The card builds a small ritual: fill it at the same time each night, hold it in the same place, pair it with a slow exhale and one sentence (I am in my bed, it is tonight). Add one more sense if the client wants (a scent on the pillow, a soft sound). Keep it a comfort, not a test of whether sleep comes. Watch for the client who drops it the first night it does not work.', '[{"id": "f0", "type": "textarea", "label": "The time I will fill the bottle, and where I will hold it (belly, chest, neck, feet):"}, {"id": "f1", "type": "textarea", "label": "The sentence I will say as the warmth settles in:"}, {"id": "f2", "type": "textarea", "label": "One other sense I will add: a scent, a sound, a texture:"}, {"id": "f3", "type": "textarea", "label": "What my body usually does at bedtime, and what I noticed it do tonight:"}, {"id": "f4", "type": "textarea", "label": "After one week: the nights I used it, and what changed in the bracing, if anything:"}]'::jsonb, array['PTSD and trauma', 'self-soothing', 'sleep']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('surprise-touch-from-behind-agreement-for-partners', 'Surprise Touch From Behind Agreement for Partners', 'couples'::resource_kind, 'An agreement for a couple where an unexpected touch from behind sends one partner into alarm.', 'Use it to give both partners a shared plan for approach, touch and recovery that neither has to explain each time.', array['Couples']::text[], '30 minutes in session', 'A hand on the shoulder from behind can be love to one partner and threat to the other''s body, and both partners end up hurt: one flinches, the other feels rejected. The agreement asks the partner who startles what approaches work (a word first, from the front, a name before a hand) and what helps afterward; it asks the other partner what the flinch feels like and what they need to not take it personally. Neither partner is asked to explain the history. Watch for the partner who promises to never touch again; the goal is touch that works, not no touch.', '[{"id": "f0", "type": "textarea", "label": "Partner who startles: the approaches that work for my body (from the front, a word first, a name before a hand):"}, {"id": "f1", "type": "textarea", "label": "Partner who startles: what helps me settle after a startle, and what makes it worse:"}, {"id": "f2", "type": "textarea", "label": "Other partner: what the flinch feels like on my side, honestly:"}, {"id": "f3", "type": "textarea", "label": "Other partner: what I need to hear or do so I do not take it personally:"}, {"id": "f4", "type": "textarea", "label": "Our shared signal that a touch is coming, and our phrase for ''I am okay, give me a second'':"}, {"id": "f5", "type": "textarea", "label": "After two weeks: what has changed in how we approach each other:"}]'::jsonb, array['PTSD and trauma', 'couples', 'safety']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('new-mole-or-rash-health-worry-delay-sheet', 'New Mole or Rash Health Worry Delay Sheet', 'worksheet'::resource_kind, 'A delay-and-decide sheet for a new mark on the skin that the client is already searching online.', 'Use it to replace repeated searching with one planned action and a dated decision about seeing a doctor.', array['Adults', 'Teens']::text[], '15 minutes', 'A new freckle or rash is the most common trigger of health worry, and the response, hours of image searching, makes it worse. The sheet asks for the plain description of the mark, the searches done so far and what they produced, one rule for the next week (a photo today, a second photo in seven days, no searching) and the dated decision point: if it has changed or the worry has not eased, book the appointment. Booking is a fine outcome; the sheet is against the loop, not the doctor. Watch for the client who checks the mark in the mirror hourly; that goes on the log too.', '[{"id": "f0", "type": "textarea", "label": "The mark, described in plain words, and when I first noticed it:"}, {"id": "f1", "type": "textarea", "label": "The searches I have done so far, how long they took, and whether they reassured me:"}, {"id": "f2", "type": "textarea", "label": "My rule for the next seven days (photo today, photo on day seven, no searching in between):"}, {"id": "f3", "type": "textarea", "label": "How many times a day I check it in the mirror, and the number I will aim for:"}, {"id": "f4", "type": "textarea", "label": "The dated decision: on day seven, if ___ then I book the appointment, otherwise I ___:"}, {"id": "f5", "type": "textarea", "label": "Day seven: what I see, what I decided, and how the worry moved over the week:"}]'::jsonb, array['anxiety', 'health', 'checking']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('the-doctor-would-have-called-by-now-probability-sheet', 'The Doctor Would Have Called by Now Probability Sheet', 'cbt'::resource_kind, 'A probability sheet for the silence after a test, where no call becomes proof of bad news.', 'Use it to put numbers next to a client''s certainty and to separate how a clinic actually works from how fear says it does.', array['Adults']::text[], '15 minutes', 'Waiting for results, the client reads silence two ways at once: if it were fine they would have called, and if it were bad they would have called. The sheet asks for the exact belief and the confidence in it, then for what the client knows about how this clinic returns results (a portal, a letter, only if abnormal, a nurse days later), and asks them to re-rate. It ends with one allowed action (a single call to the office at a set time) and what they will do with the rest of the day. Watch for the client who checks the portal every few minutes; count the checks.', '[{"id": "f0", "type": "textarea", "label": "What I am waiting for, and how long it has been:"}, {"id": "f1", "type": "textarea", "label": "The belief about the silence, in its exact words, and my confidence in it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What I actually know about how this office returns results:"}, {"id": "f3", "type": "textarea", "label": "Other explanations for no call yet, listed without arguing with them:"}, {"id": "f4", "type": "textarea", "label": "My confidence now, and the one call I will allow myself, at what time:"}, {"id": "f5", "type": "textarea", "label": "What I will do with the hours in between, and how many times I checked the portal today:"}]'::jsonb, array['anxiety', 'probability', 'health']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('anxious-mind-as-a-nervous-flight-attendant-page', 'Anxious Mind as a Nervous Flight Attendant Page', 'act'::resource_kind, 'A defusion metaphor for a mind that keeps announcing turbulence and demonstrating the exits on a smooth flight.', 'Use it to help a client hear anxious announcements as a well-meaning voice over the speaker, not as the pilot.', array['Adults', 'Teens']::text[], '15 minutes', 'The anxious mind is a flight attendant who means well and cannot stop: brace, check your seatbelt, locate the nearest exit, this could get bumpy. The page asks the client to collect the announcements their mind made this week, notice their tone (urgent, repetitive, rarely about anything that happened), and practice the posture of a seasoned passenger: hearing the announcement, nodding, going back to the book. The pilot is the client''s chosen direction. Watch for the client who argues with the announcements; the passenger does not debate the attendant.', '[{"id": "f0", "type": "textarea", "label": "The announcements my mind made this week, in flight attendant voice:"}, {"id": "f1", "type": "textarea", "label": "How often the announced turbulence actually arrived:"}, {"id": "f2", "type": "textarea", "label": "What a seasoned passenger does when the announcement plays, and what I usually do instead:"}, {"id": "f3", "type": "textarea", "label": "The book I will go back to: the thing I was doing or value I was serving:"}, {"id": "f4", "type": "textarea", "label": "One announcement this week I nodded at and kept reading, and how it went:"}]'::jsonb, array['anxiety', 'defusion', 'metaphor']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('cope-ahead-for-the-jury-selection-day-card', 'Cope Ahead for the Jury Selection Day Card', 'dbt'::resource_kind, 'A cope-ahead card for a day of waiting, being called by name and answering questions in a courtroom.', 'Use it to rehearse the hard moments of a civic obligation in imagination so the day itself has fewer surprises.', array['Adults']::text[], '20 minutes the week before', 'Jury selection packs several anxiety triggers into one day: long unstructured waiting, a name called over a loudspeaker, questions asked in front of strangers, no control over the schedule. The card walks cope ahead: describe the situation, name the emotions likely to show up, decide which skills fit each moment (paced breathing in the waiting room, a scripted answer for the questions, a self-soothe item in the bag), rehearse it vividly in imagination, and plan the recovery afterward. Watch for the client who rehearses the catastrophe instead of the coping.', '[{"id": "f0", "type": "textarea", "label": "The day, step by step, as I understand it will go:"}, {"id": "f1", "type": "textarea", "label": "The moments I expect to be hardest, and the emotion I expect at each:"}, {"id": "f2", "type": "textarea", "label": "The skill I will use at each hard moment, named specifically:"}, {"id": "f3", "type": "textarea", "label": "My imagined rehearsal: write it in the present tense, using the skills and getting through:"}, {"id": "f4", "type": "textarea", "label": "What I will have in my bag and in my pocket:"}, {"id": "f5", "type": "textarea", "label": "The recovery plan for the evening after, whether I was picked or sent home:"}]'::jsonb, array['anxiety', 'cope ahead', 'core DBT']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('worry-appeal-court-group-verdict-game', 'Worry Appeal Court Group Verdict Game', 'game'::resource_kind, 'A courtroom game in which a worry is put on trial and the group votes on whether it is proven or dismissed.', 'Use it to let a group practice weighing a worry''s evidence with distance and some humor.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Rules: a volunteer offers a worry (not a crisis) and states it as a charge: ''I will embarrass myself at the party.'' One player is the prosecutor and argues the evidence for; one is the defense and argues the evidence against; the rest are the jury and may ask one question each. The jury votes: proven, dismissed, or not enough evidence. Rotate roles so everyone defends a worry that is not their own. Debrief: what it was like to hear your worry argued by someone else, and which side had more facts. Watch for the prosecutor who gets personal; keep it to evidence.', '[{"id": "f0", "type": "textarea", "label": "The worry I put on trial, stated as a charge:"}, {"id": "f1", "type": "textarea", "label": "The prosecutor''s strongest evidence, and whether it was fact or feeling:"}, {"id": "f2", "type": "textarea", "label": "The defense''s strongest evidence:"}, {"id": "f3", "type": "textarea", "label": "The jury''s verdict, and what it was like to hear it:"}, {"id": "f4", "type": "textarea", "label": "Defending someone else''s worry: what I noticed that I miss when it is my own:"}]'::jsonb, array['anxiety', 'group', 'game']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('open-the-curtains-first-thing-micro-step-sheet', 'Open the Curtains First Thing Micro Step Sheet', 'worksheet'::resource_kind, 'A one-action sheet for the morning: curtains open before anything else, logged for two weeks.', 'Use it to give a client in a low stretch one tiny morning act that lets light in and counts as done.', array['Adults', 'Teens']::text[], 'One minute daily for two weeks', 'When mornings are heavy, the first act sets the day, and opening the curtains is small enough to do from the bed. The sheet asks for the time the client usually wakes, the curtains they will open, and a two-week log: done or not, the weather outside, and one word for the mood an hour later. Do not add a second step for two weeks. Watch for the client who skips it because the day is gray; the point is the act, not the sunshine, and a gray day opened still counts.', '[{"id": "f0", "type": "textarea", "label": "The window I will open first, and roughly what time:"}, {"id": "f1", "type": "textarea", "label": "What usually happens in my first ten minutes awake now:"}, {"id": "f2", "type": "textarea", "label": "Week one log: each day, done or not, the sky outside, and one word for my mood an hour later:"}, {"id": "f3", "type": "textarea", "label": "Week two log: the same:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the days I opened them and the days I did not:"}, {"id": "f5", "type": "textarea", "label": "The next tiny thing I might add after this one is a habit (not yet):"}]'::jsonb, array['depression', 'behavioral activation', 'routine']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('nobody-would-notice-if-i-skipped-the-party-sheet', 'Nobody Would Notice If I Skipped the Party Sheet', 'cbt'::resource_kind, 'A thought record for the belief that the client''s absence goes unnoticed, used before declining an invitation.', 'Use it to test a mind-reading thought that keeps a low client home and to set up a small check of it.', array['Adults', 'Teens']::text[], '15 minutes', 'In a low stretch, ''nobody would notice'' feels like plain fact and makes staying home feel considerate rather than avoidant. The sheet asks for the thought and the evidence the client has for it, the evidence against (who texted, who asked last time), what noticing would even look like from the outside, and one small check: go for forty minutes, or ask one person afterward whether they noticed. If the thought shades into not mattering at all, move to a safety conversation and name 988 (call or text). Watch for the client who skips and reads the quiet as confirmation.', '[{"id": "f0", "type": "textarea", "label": "The invitation, and the thought that showed up about going:"}, {"id": "f1", "type": "textarea", "label": "Evidence that nobody would notice my absence:"}, {"id": "f2", "type": "textarea", "label": "Evidence that someone would (who invited me, who texted, who asked last time):"}, {"id": "f3", "type": "textarea", "label": "What ''noticing'' would actually look like from the outside, and whether I would see it:"}, {"id": "f4", "type": "textarea", "label": "A small check I am willing to run: go for a set time, or ask one person afterward:"}, {"id": "f5", "type": "textarea", "label": "If the thought is bigger than this party, the person I will tell this week, and 988 (call or text) if it gets heavy:"}]'::jsonb, array['depression', 'mind reading', 'avoidance']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('low-mood-as-a-long-layover-not-the-destination-page', 'Low Mood as a Long Layover Not the Destination Page', 'act'::resource_kind, 'An acceptance metaphor for a low stretch as a layover: real, dull, not where the client is going.', 'Use it to help a client sit in a low period without concluding it is permanent, and to find small valued acts in the terminal.', array['Adults', 'Teens']::text[], '20 minutes', 'A long layover is miserable in an ordinary way: the chairs are bad, the time crawls, nothing is happening, and it is not where you live. The page invites the client to treat a low stretch the same way: notice the mind announcing that the terminal is the whole trip, name the destination (the values they are still traveling toward), and find the small things a seasoned traveler does in a terminal (a walk, a call, a window). It never promises when the next flight boards. Watch for the client who takes the metaphor as a promise; it is a way of standing, not a forecast.', '[{"id": "f0", "type": "textarea", "label": "What the terminal is like right now: the dullness, the thoughts that say this is permanent:"}, {"id": "f1", "type": "textarea", "label": "The destination I am still traveling toward, in my own words (values, not outcomes):"}, {"id": "f2", "type": "textarea", "label": "What a seasoned traveler does in a long layover, and which of those I could do today:"}, {"id": "f3", "type": "textarea", "label": "The sentence I will use when the mind says the terminal is the whole trip:"}, {"id": "f4", "type": "textarea", "label": "One small thing I did in the terminal this week that was mine, and what it was like:"}]'::jsonb, array['depression', 'acceptance', 'metaphor']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('build-mastery-by-returning-one-overdue-library-book-card', 'Build Mastery by Returning One Overdue Library Book Card', 'dbt'::resource_kind, 'A build-mastery card for one small overdue errand that has grown heavy with avoidance and shame.', 'Use it to give a low client one finishable task with a clear end, and to notice what completing it does.', array['Adults', 'Teens']::text[], '30 minutes once', 'Build mastery is doing one thing a little hard that leaves the client feeling capable, and an overdue library book, a package to return, an unreturned borrowed dish is the perfect size: small, specific, finished the moment it is done. The card asks for the errand, the thoughts that have kept it undone (they will judge me, the fine will be huge), the plan down to the hour, and a rating of capability before and after. Then one more for next week. Watch for the client who picks something too big; the fine is usually a few dollars and the librarian does not care.', '[{"id": "f0", "type": "textarea", "label": "The small overdue thing, and how long it has waited:"}, {"id": "f1", "type": "textarea", "label": "The thoughts that have kept it undone, in their exact words:"}, {"id": "f2", "type": "textarea", "label": "My plan: the day, the hour, how I get there, what I say if anything:"}, {"id": "f3", "type": "textarea", "label": "How capable I feel right now, 0 to 10:"}, {"id": "f4", "type": "textarea", "label": "After: what actually happened, how capable I feel now, and how long the whole thing took:"}, {"id": "f5", "type": "textarea", "label": "The next overdue small thing I will pick for next week:"}]'::jsonb, array['depression', 'build mastery', 'core DBT']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('low-stretch-weekend-plans-sheet-for-partners', 'Low Stretch Weekend Plans Sheet for Partners', 'couples'::resource_kind, 'A shared plan for weekends when one partner is in a low stretch and the other wants to do things together.', 'Use it to give both partners a menu that neither reads as pressure or abandonment.', array['Couples']::text[], '20 minutes on a Thursday', 'A low partner wants to be left alone and not left behind; a well partner wants company and does not want to nag. Saturdays become a standoff. The sheet asks the low partner for the smallest version of ''together'' they could manage (coffee on the porch, a drive with no stops), what help looks like and what pressure looks like, and asks the other partner what they will do on their own without resentment and how they will invite without pushing. Agree on one shared thing and one solo thing each. Watch for the well partner who cancels their own plans to supervise; that helps nobody.', '[{"id": "f0", "type": "textarea", "label": "Low partner: the smallest version of together I could manage this weekend:"}, {"id": "f1", "type": "textarea", "label": "Low partner: what feels like help, and what feels like pressure, with examples:"}, {"id": "f2", "type": "textarea", "label": "Other partner: what I will do on my own this weekend that I actually want to do:"}, {"id": "f3", "type": "textarea", "label": "Other partner: how I will invite once, and what I will say if the answer is no:"}, {"id": "f4", "type": "textarea", "label": "Our one shared thing and our one solo thing each, written down:"}, {"id": "f5", "type": "textarea", "label": "Sunday night: what happened, and what we would change for next weekend:"}]'::jsonb, array['depression', 'couples', 'support']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('winter-gear-lost-and-found-checkpoint-sheet', 'Winter Gear Lost and Found Checkpoint Sheet', 'worksheet'::resource_kind, 'A checkpoint sheet for hats, gloves and scarves that vanish between the car, the office and the house.', 'Use it to set up two fixed checkpoints a day where winter gear gets counted and parked.', array['Adults', 'Teens']::text[], '15 minutes to set up, then daily', 'Winter adds four items to every exit, and a client who already loses keys now loses a glove a week and spends money and shame replacing them. The sheet names the gear, picks two checkpoints (the car door and the front door) and one parking spot at each, and sets a three-second count the client does out loud: hat, gloves, scarf, keys. It logs lost items for two weeks so the client can see the drop. Watch for the client who designs a beautiful system and skips the count; the count is the system.', '[{"id": "f0", "type": "textarea", "label": "The gear I carry in winter, and what I lost last year, roughly:"}, {"id": "f1", "type": "textarea", "label": "My two checkpoints and the parking spot at each (a hook, a basket, the passenger seat):"}, {"id": "f2", "type": "textarea", "label": "The count I will say out loud at each checkpoint, in order:"}, {"id": "f3", "type": "textarea", "label": "Week one: items lost, and where the count got skipped:"}, {"id": "f4", "type": "textarea", "label": "Week two: the same, and what changed:"}, {"id": "f5", "type": "textarea", "label": "What I will do when something still goes missing, instead of the shame spiral:"}]'::jsonb, array['ADHD', 'executive function', 'routine']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('if-i-miss-the-first-step-i-should-give-up-belief-sheet', 'If I Miss the First Step I Should Give Up Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the all-or-nothing rule that a plan missed at step one is a plan ruined.', 'Use it to loosen a rule that turns one late start into a lost day and to practice rejoining mid-plan.', array['Adults', 'Teens']::text[], '15 minutes', 'A client with attention difficulties misses the 7 a.m. start, concludes the day is already blown, and does nothing until evening. The sheet names the rule, asks where it came from, lists its costs this month, tests it against a day where a late start still went fine, and rewrites it as something more workable: a plan joined at step three is still a plan. It ends with a rehearsal of the next late start. Watch for the client who turns the new rule into a new standard to fail at; keep it kind.', '[{"id": "f0", "type": "textarea", "label": "The rule, in its exact words:"}, {"id": "f1", "type": "textarea", "label": "Where I think I learned it, and who else talks like this:"}, {"id": "f2", "type": "textarea", "label": "What the rule has cost me this month: the days it wrote off:"}, {"id": "f3", "type": "textarea", "label": "A day when I started late and the day was still partly fine:"}, {"id": "f4", "type": "textarea", "label": "The rewrite: a rule about missed first steps I could actually live by:"}, {"id": "f5", "type": "textarea", "label": "The next time I miss step one, the exact step I will join at and what I will say to myself:"}]'::jsonb, array['ADHD', 'all-or-nothing', 'core beliefs']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('values-when-the-email-draft-sits-unsent-page', 'Values When the Email Draft Sits Unsent Page', 'act'::resource_kind, 'A committed action page for the message that is written, reread and never sent.', 'Use it to connect sending an imperfect message to a value and to practice the send as a small valued act.', array['Adults', 'Teens']::text[], '15 minutes, then one send', 'The draft exists, the client has reread it a dozen times, and it sits in the folder while the mind insists it needs one more pass. The page asks what the message is for (keeping a commitment, asking for help, repairing something), the value that makes it matter, what the mind says will go wrong if it is sent as is, and whether the client is willing to send the imperfect version in service of the value. Then the send, and a note on what happened. Watch for the client who improves the draft as the exercise; the exercise is pressing the button.', '[{"id": "f0", "type": "textarea", "label": "The message, and how long it has sat in drafts:"}, {"id": "f1", "type": "textarea", "label": "What it is for, and the value behind it, in my own words:"}, {"id": "f2", "type": "textarea", "label": "What my mind says will go wrong if I send it as it is:"}, {"id": "f3", "type": "textarea", "label": "Am I willing to have those thoughts and press send anyway, for that value?"}, {"id": "f4", "type": "textarea", "label": "The time I will send it today, and the one small thing I will do right after:"}, {"id": "f5", "type": "textarea", "label": "What actually happened once it was sent:"}]'::jsonb, array['ADHD', 'values', 'committed action']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-doom-scrolling-past-bedtime-card', 'Opposite Action to Doom Scrolling Past Bedtime Card', 'dbt'::resource_kind, 'An opposite action card for the pull to keep scrolling long after the body wants to sleep.', 'Use it to give a client an all-the-way opposite move for the phone at bedtime, with the body leading.', array['Adults', 'Teens']::text[], 'Nightly for two weeks', 'Scrolling past bedtime is an urge that feeds on tiredness, and a client with attention difficulties often loses two hours a night to it and the next morning too. Opposite action here is physical and all the way: phone across the room, lights down, body horizontal, eyes closed, and a replacement for the hands (a book, a fidget, a warm mug). The card asks what the urge says, what the opposite move is tonight, and what happens when it is done fully rather than halfway. Watch for the client who keeps the phone on the nightstand ''just for the alarm''; buy an alarm clock.', '[{"id": "f0", "type": "textarea", "label": "What the urge says at bedtime, in its exact words:"}, {"id": "f1", "type": "textarea", "label": "What the scrolling actually does for me, and what it costs me the next day:"}, {"id": "f2", "type": "textarea", "label": "My all-the-way opposite action: where the phone goes, where I go, what my hands hold:"}, {"id": "f3", "type": "textarea", "label": "The time I will do this each night, and how I will know it is time:"}, {"id": "f4", "type": "textarea", "label": "Nightly log: did it, half did it, or scrolled, and how the morning felt:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: what changed, and what I want to adjust:"}]'::jsonb, array['ADHD', 'opposite action', 'sleep']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('masking-tape-step-path-to-the-finished-chore-craft', 'Masking Tape Step Path to the Finished Chore Craft', 'kids'::resource_kind, 'A craft in which a child tapes a path of steps across the floor to a chore and walks it one square at a time.', 'Use it to help a child who freezes at a big task see it as a few floor squares, with the parent walking it with them.', array['Children']::text[], '20 minutes to build, then use', 'A child told to clean their room sees one impossible thing; a child who tapes four squares on the floor (books, clothes, toys, bed) sees four small ones. The child and parent make the path with masking tape, write or draw one step in each square, and the child walks the path doing each step before moving on, with the parent standing at the end of it. Keep it to five squares or fewer. Watch for the parent who adds squares mid-task; the path is agreed before the first step.', '[{"id": "f0", "type": "textarea", "label": "The chore I usually freeze on:"}, {"id": "f1", "type": "textarea", "label": "The squares on my path, in order (draw them):"}, {"id": "f2", "type": "textarea", "label": "What my grown-up does while I walk it (cheer at the end, help with one square, stay quiet):"}, {"id": "f3", "type": "textarea", "label": "The square that was hardest, and how I got through it:"}, {"id": "f4", "type": "textarea", "label": "Another chore I could make a path for:"}]'::jsonb, array['ADHD', 'children', 'task initiation']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('bar-gift-cards-and-leftover-supplies-clear-out-sheet', 'Bar Gift Cards and Leftover Supplies Clear Out Sheet', 'worksheet'::resource_kind, 'A clear-out sheet for the gift cards, bottles, pipes and apps that still live in the client''s home and phone.', 'Use it to make a dated plan for removing the easy routes to substance use and for the feelings that come with each one.', array['Adults']::text[], '30 minutes, then the clear-out', 'A client working on substance use often still has a drawer, a glove box or a folder of apps that make the next use easy. The sheet lists what is where, what each item means (a gift from a friend, a just-in-case), the feeling attached to getting rid of it, and a dated plan for each: give away, pour out, delete, hand to a trusted person. It also asks who will be with them when they do it. Watch for the client who keeps one thing for guests; put that on the sheet and decide it on purpose.', '[{"id": "f0", "type": "textarea", "label": "What is still in my home, car or phone that makes use easy, and where:"}, {"id": "f1", "type": "textarea", "label": "What each item means to me, and the feeling that comes up about removing it:"}, {"id": "f2", "type": "textarea", "label": "My plan for each: give away, pour out, delete, or hand to someone, with a date:"}, {"id": "f3", "type": "textarea", "label": "Who will be with me or on the phone while I do it:"}, {"id": "f4", "type": "textarea", "label": "The one thing I am tempted to keep ''for guests,'' and my honest decision about it:"}, {"id": "f5", "type": "textarea", "label": "After: what I removed, what I kept, and what the house feels like now:"}]'::jsonb, array['addiction', 'substance use', 'planning']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('switching-to-something-lighter-counts-as-quitting-sheet', 'Switching to Something Lighter Counts as Quitting Sheet', 'cbt'::resource_kind, 'A thought record for the bargain of swapping one substance for a lighter one and calling it a change.', 'Use it to look honestly at a substitution thought without shaming the client for having it.', array['Adults']::text[], '20 minutes', 'Beer instead of liquor, edibles instead of smoking, weekends only: the mind offers a lighter version and calls it progress. Sometimes it is a real step; sometimes it is the urge negotiating. The sheet asks for the exact bargain, what the client hopes it will do, what their own goal was before the bargain appeared, what happened the last time a similar swap was made, and who they could run the plan past. The clinician helps weigh it; the sheet does not decide. Watch for the bargain that arrives at the same hour as the urge.', '[{"id": "f0", "type": "textarea", "label": "The swap my mind is offering, in its exact words:"}, {"id": "f1", "type": "textarea", "label": "What I hope it will do for me, honestly:"}, {"id": "f2", "type": "textarea", "label": "The goal I set for myself before this idea showed up:"}, {"id": "f3", "type": "textarea", "label": "The last time I made a similar swap: what happened over the following month:"}, {"id": "f4", "type": "textarea", "label": "When this idea tends to arrive (the hour, the mood, the company):"}, {"id": "f5", "type": "textarea", "label": "Who I will run the plan past before acting on it, and what I expect them to say:"}]'::jsonb, array['addiction', 'substance use', 'thinking traps']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('urge-as-a-song-stuck-in-my-head-page', 'Urge as a Song Stuck in My Head Page', 'act'::resource_kind, 'A defusion page that treats an urge like an earworm: loud, repetitive, and not an instruction.', 'Use it to help a client let an urge play without singing along or trying to force it out.', array['Adults', 'Teens']::text[], '15 minutes', 'Everyone knows what a song stuck in the head is like: it plays whether you want it or not, fighting it makes it louder, and it fades when attention moves on. The page asks the client to notice the urge as a chorus (its words, its hook, when it starts up), to practice letting it play while doing the next thing, and to notice how it fades without being obeyed or fought. It never promises the song stops on command. Watch for the client who hums along, rehearsing where they would get it; that is singing the chorus.', '[{"id": "f0", "type": "textarea", "label": "The urge''s chorus: the words and pictures it repeats:"}, {"id": "f1", "type": "textarea", "label": "When it tends to start playing, and what turns the volume up:"}, {"id": "f2", "type": "textarea", "label": "What happens when I fight it, and what happens when I obey it:"}, {"id": "f3", "type": "textarea", "label": "The next thing I will do while it plays, chosen on purpose:"}, {"id": "f4", "type": "textarea", "label": "One time this week I let it play and did the next thing anyway, and how long until it faded:"}]'::jsonb, array['addiction', 'urges', 'defusion']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-the-craving-in-the-grocery-wine-aisle-card', 'Mindfulness of the Craving in the Grocery Wine Aisle Card', 'dbt'::resource_kind, 'A mindfulness card for the aisle the client has to walk past every week to buy dinner.', 'Use it to turn a weekly trigger into a practice of observing an urge without acting, with a clear exit if needed.', array['Adults']::text[], 'Five minutes weekly', 'The grocery store puts the wine or beer aisle on the way to the milk, and a client working on substance use cannot avoid the store forever. The card is a short practice for that aisle: notice the urge arrive, describe it as sensation and thought without judging, keep walking at a steady pace, and name what is in the cart that the trip was for. It includes a plain exit (leave the cart, go to the car, call someone) if the urge is too strong today. Watch for the client who routes through the aisle on purpose as a test.', '[{"id": "f0", "type": "textarea", "label": "Where the aisle is in my store, and the route I take to avoid or pass it:"}, {"id": "f1", "type": "textarea", "label": "What the urge feels like in my body when I pass it: sensations, in plain words:"}, {"id": "f2", "type": "textarea", "label": "The thoughts that come with it, written without arguing:"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself as I keep walking, and what the trip was actually for:"}, {"id": "f4", "type": "textarea", "label": "My exit if it is too strong today: leave the cart, the car, who I call:"}, {"id": "f5", "type": "textarea", "label": "After this week''s trip: what I noticed, and how the urge changed as I kept walking:"}]'::jsonb, array['addiction', 'urges', 'mindfulness']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('partner-not-sponsor-roles-talk-sheet-for-partners', 'Partner Not Sponsor Roles Talk Sheet for Partners', 'couples'::resource_kind, 'A roles conversation for a couple where one partner has slipped into monitoring the other''s substance use.', 'Use it to help both partners name what belongs to the relationship and what belongs to the client''s own recovery supports.', array['Couples']::text[], 'Full session', 'When one partner works on substance use, the other often becomes a watcher: counting bottles, checking breath, asking where they were. Both partners end up lonely in it. The sheet asks the partner working on use what support feels like and what surveillance feels like, and asks the other partner what they are afraid will happen if they stop watching and who else holds that fear with them. Together they name which questions belong in the relationship and which belong to a sponsor, group or counselor. Watch for the pair who agree to no questions at all; some belong.', '[{"id": "f0", "type": "textarea", "label": "Partner working on use: what support from you feels like, with examples:"}, {"id": "f1", "type": "textarea", "label": "Partner working on use: what feels like being watched, and what it does to me:"}, {"id": "f2", "type": "textarea", "label": "Other partner: what I am afraid will happen if I stop watching:"}, {"id": "f3", "type": "textarea", "label": "Other partner: who else can hold that fear with me so it is not only on us two:"}, {"id": "f4", "type": "textarea", "label": "Together: the questions that belong between us, and the ones that belong to other supports:"}, {"id": "f5", "type": "textarea", "label": "The check-in we will keep: how often, what it covers, and what it will not become:"}]'::jsonb, array['addiction', 'couples', 'boundaries']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('slow-walker-blocking-the-sidewalk-irritation-log-sheet', 'Slow Walker Blocking the Sidewalk Irritation Log Sheet', 'worksheet'::resource_kind, 'A log of small public irritations, the slow walker and the blocked aisle, for a client whose fuse is short.', 'Use it to track the little daily heat before it becomes the big one and to notice what the body does each time.', array['Adults', 'Teens']::text[], 'One week', 'The big blowups get the attention, but the slow walker, the person who stops at the top of the escalator and the cart left in the aisle are where many clients burn their fuse down by noon. The log asks for each small irritation: the moment, the heat from 0 to 10, the body sign, the thought (they should know better), and what the client did. By day three the pattern usually shows. Watch for the client who logs only the other person''s failures; the thought column is where the work is.', '[{"id": "f0", "type": "textarea", "label": "Each small irritation this week: where, who, what they did:"}, {"id": "f1", "type": "textarea", "label": "The heat each time, 0 to 10, and the first body sign (jaw, chest, hands, pace):"}, {"id": "f2", "type": "textarea", "label": "The thought each time, in its exact words:"}, {"id": "f3", "type": "textarea", "label": "What I did: sighed, muttered, sped up, said something, let it go:"}, {"id": "f4", "type": "textarea", "label": "What I notice after a week: the time of day, the kind of person, the thought that repeats:"}, {"id": "f5", "type": "textarea", "label": "One irritation I will meet differently next week, and how:"}]'::jsonb, array['anger management', 'self-monitoring', 'triggers']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('the-referee-is-out-to-get-us-thought-record', 'The Referee Is Out to Get Us Thought Record', 'cbt'::resource_kind, 'A thought record for the sideline or the couch, where a bad call becomes proof of a plot against the client''s team.', 'Use it to catch hostile intent reading in a safe, slightly absurd setting before it is tested at work or at home.', array['Adults', 'Teens']::text[], '15 minutes after a game', 'Sports are a low-stakes place to catch a habit that costs a lot elsewhere: reading bad luck as malice. The record asks for the call, the thought (they are out to get us, that was personal), the heat it produced, the evidence for a plot versus a tired human making a fast judgment, and what the same thought sounds like at work or in the family. Keep it light; the point is the pattern. Watch for the client who is amused by the sports version and defends it fiercely at work.', '[{"id": "f0", "type": "textarea", "label": "The call, and the thought that followed, in its exact words:"}, {"id": "f1", "type": "textarea", "label": "How hot I got, 0 to 10, and how long it lasted:"}, {"id": "f2", "type": "textarea", "label": "Evidence for a plot against my team:"}, {"id": "f3", "type": "textarea", "label": "Evidence for an ordinary human making a fast call under pressure:"}, {"id": "f4", "type": "textarea", "label": "The same thought in another part of my life this month (work, family, traffic):"}, {"id": "f5", "type": "textarea", "label": "A sentence about bad calls I could carry to both places:"}]'::jsonb, array['anger management', 'mind reading', 'thought record']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('fairness-rule-versus-peace-choice-point-page', 'Fairness Rule Versus Peace Choice Point Page', 'act'::resource_kind, 'A choice point page for the moment when insisting on what is fair would cost the client the evening.', 'Use it to help a client notice the fairness rule as a hook and choose, in the moment, between the rule and the value.', array['Adults', 'Teens']::text[], '20 minutes', 'Many angry clients are running a fairness rule: if it is not fair, I cannot let it go. The rule is honorable and expensive. The page sets up the choice point: the situation, the hook (that is not fair), the two moves (toward the rule, toward the value of peace or connection or rest), and what each costs. It does not say fairness never wins; it asks the client to choose with eyes open. Watch for the client who hears this as being told to be a doormat; the choice is theirs each time.', '[{"id": "f0", "type": "textarea", "label": "A recent moment where fairness and peace pulled in different directions:"}, {"id": "f1", "type": "textarea", "label": "The hook, in its exact words:"}, {"id": "f2", "type": "textarea", "label": "The move toward the rule: what I would do, and what it would cost tonight:"}, {"id": "f3", "type": "textarea", "label": "The move toward the value: what I would do, and what it would cost me inside:"}, {"id": "f4", "type": "textarea", "label": "What I actually want more of in my life, in my own words:"}, {"id": "f5", "type": "textarea", "label": "The next time the hook shows up, the question I will ask myself before I move:"}]'::jsonb, array['anger management', 'choice point', 'values']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-posting-the-angry-review-grid', 'Pros and Cons of Posting the Angry Review Grid', 'dbt'::resource_kind, 'A pros and cons grid for the one-star review the client is about to post about a business or a person.', 'Use it to slow a public act of anger and weigh its short-term relief against its longer costs.', array['Adults', 'Teens']::text[], '15 minutes before posting', 'The angry review is anger with a publish button: it feels like justice and lasts forever. The grid asks the client to fill four boxes before posting: pros of posting, cons of posting, pros of not posting, cons of not posting, both now and in a month. Then it asks what the review is for (warning others, being heard, punishing) and whether a different action gets that better. The client decides. Watch for the client who writes the review as a draft to feel better and then posts it anyway at midnight; add a sleep-on-it line.', '[{"id": "f0", "type": "textarea", "label": "What happened, in plain facts, and what I want to post:"}, {"id": "f1", "type": "textarea", "label": "Pros of posting, now and in a month:"}, {"id": "f2", "type": "textarea", "label": "Cons of posting, now and in a month:"}, {"id": "f3", "type": "textarea", "label": "Pros and cons of not posting:"}, {"id": "f4", "type": "textarea", "label": "What the review is really for, and whether something else would get that better:"}, {"id": "f5", "type": "textarea", "label": "My decision, and the time I will revisit it if I decide to wait:"}]'::jsonb, array['anger management', 'pros and cons', 'core DBT']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('grumpy-cat-poker-face-challenge-game', 'Grumpy Cat Poker Face Challenge Game', 'game'::resource_kind, 'A game in which players keep a neutral face while teammates try to provoke a reaction with silly, not cruel, tactics.', 'Use it to practice staying regulated under provocation in a group, with a debrief on what worked inside.', array['Groups', 'Children', 'Teens']::text[], '15 minutes', 'Rules: one player sits in the chair and holds a neutral face for sixty seconds while the others take turns trying to make them react with jokes, faces and silly noises; no touching, no insults, no personal content. A laugh or a scowl ends the turn. Everyone gets a turn in the chair. Debrief: what did you do inside to keep the face (breathing, looking at one spot, a phrase), what nearly broke you, and where in your week do you need that face. Watch for the provoker who goes personal; stop and restate the rules.', '[{"id": "f0", "type": "textarea", "label": "How long I held my face, and what finally broke it, if anything:"}, {"id": "f1", "type": "textarea", "label": "What I did inside to stay steady (breath, a spot on the wall, a phrase):"}, {"id": "f2", "type": "textarea", "label": "What was hardest to not react to:"}, {"id": "f3", "type": "textarea", "label": "What it was like to be the provoker, and how I knew where the line was:"}, {"id": "f4", "type": "textarea", "label": "A moment this week where I need the poker face, and the inside trick I will use:"}]'::jsonb, array['anger management', 'group', 'game']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('retracing-my-steps-to-check-i-hit-nothing-log-sheet', 'Retracing My Steps to Check I Hit Nothing Log Sheet', 'worksheet'::resource_kind, 'A log for the urge to drive back and check the road after a bump or a shadow, for a client stuck in the loop.', 'Use it to count the retracing, time it, and record what the check actually found, with a planned delay.', array['Adults']::text[], 'Two weeks', 'The bump might have been a pothole; the mind says it might have been a person. Driving back to check brings a minute of relief and a stronger urge next time. The log asks for each urge: the trigger, the certainty that something happened (0 to 100), whether the client drove back, how long the detour took, what the check found, and the certainty afterward. In week two it adds a planned delay before any check. The clinician decides the pace. Watch for the client who checks the news instead of the road; that goes in the log too.', '[{"id": "f0", "type": "textarea", "label": "Each urge: where I was, what I felt or saw, and how sure I was that something happened (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "Did I go back, and how long did the detour take:"}, {"id": "f2", "type": "textarea", "label": "What the check found, and how sure I was afterward:"}, {"id": "f3", "type": "textarea", "label": "Other checks I did instead: the news, the mirror, asking a passenger:"}, {"id": "f4", "type": "textarea", "label": "Week two: the delay I will try before any check, and what happened when I waited:"}, {"id": "f5", "type": "textarea", "label": "What I notice about the certainty before and after checking across two weeks:"}]'::jsonb, array['OCD', 'checking', 'self-monitoring']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('if-i-feel-disgust-it-must-be-contaminated-belief-check-sheet', 'If I Feel Disgust It Must Be Contaminated Belief Check Sheet', 'cbt'::resource_kind, 'A belief sheet for using the feeling of disgust as proof that an object or surface is dangerous.', 'Use it to separate the emotion from the evidence in a contamination worry, as groundwork before any exposure.', array['Adults', 'Teens']::text[], '20 minutes', 'Emotional reasoning is at the heart of many contamination worries: I feel disgusted, so it is dirty. The sheet asks for a recent object or surface, the disgust rating, the belief about danger, and then for the evidence that disgust tracks actual danger (it does not track well: a clean public toilet seat versus a cherished old blanket). It ends with a small observation task, not a touch task, that the clinician sets. Watch for the client who wants reassurance that the object is clean; the sheet is about the logic, not the object.', '[{"id": "f0", "type": "textarea", "label": "The object or surface, and my disgust rating, 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "What I believe about its danger, and how sure I am:"}, {"id": "f2", "type": "textarea", "label": "Things I find disgusting that are not dangerous, and things that are dangerous and not disgusting:"}, {"id": "f3", "type": "textarea", "label": "What disgust is actually telling me, if not danger:"}, {"id": "f4", "type": "textarea", "label": "A sentence that holds both: ''I feel disgust and...'':"}, {"id": "f5", "type": "textarea", "label": "The small observation task we agreed on, and what I noticed doing it:"}]'::jsonb, array['OCD', 'emotional reasoning', 'core beliefs']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('doubt-as-a-hitchhiker-i-do-not-pick-up-page', 'Doubt as a Hitchhiker I Do Not Pick Up Page', 'act'::resource_kind, 'A defusion metaphor for the doubting thought standing by the road with its thumb out at every turn.', 'Use it to help a client see the doubt, acknowledge it, and keep driving without stopping to argue or reassure.', array['Adults', 'Teens']::text[], '15 minutes', 'Doubt stands at the roadside looking harmless: did you lock it, are you sure, what if. Picking it up means a long conversation that never reaches certainty. The page asks the client to notice the hitchhiker (where it appears, what sign it holds), to practice a nod and a steady speed, and to name where the car is actually going. It does not promise the hitchhiker leaves the road. Watch for the client who slows down to read the sign more carefully; that is the stop.', '[{"id": "f0", "type": "textarea", "label": "Where my doubt hitchhiker usually stands, and what its sign says:"}, {"id": "f1", "type": "textarea", "label": "What happens when I pick it up: how long the conversation lasts, and where it ends:"}, {"id": "f2", "type": "textarea", "label": "The nod I will give it and the sentence I will say as I pass (''I see you, not today''):"}, {"id": "f3", "type": "textarea", "label": "Where the car is going: the thing I was doing or the value I was serving:"}, {"id": "f4", "type": "textarea", "label": "One time this week I drove past, and what the doubt did in the rearview mirror:"}]'::jsonb, array['OCD', 'defusion', 'metaphor']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('turning-the-mind-toward-uncertainty-at-bedtime-card', 'Turning the Mind Toward Uncertainty at Bedtime Card', 'dbt'::resource_kind, 'A turning-the-mind card for the last check of the night, when the client wants certainty before sleep.', 'Use it to practice choosing to accept not knowing, again and again, at the hour the urge to check is strongest.', array['Adults', 'Teens']::text[], 'Nightly for two weeks', 'Bedtime is when the doubt gets loudest: is the stove off, is the door locked, did I send that. Turning the mind is noticing the moment of refusal (I cannot sleep not knowing) and choosing, as many times as it takes, to turn toward not knowing. The card asks for the refusal thought, the turning sentence, a hand on the chest or another body cue for the turn, and a log of how many turns each night. The clinician sets how many checks, if any, are allowed first. Watch for the client who turns the mind once and then checks anyway.', '[{"id": "f0", "type": "textarea", "label": "What I want to be certain about at bedtime, and what I usually do to get certain:"}, {"id": "f1", "type": "textarea", "label": "The refusal thought, in its exact words:"}, {"id": "f2", "type": "textarea", "label": "My turning sentence (''I am choosing not to know tonight''), and the body cue that goes with it:"}, {"id": "f3", "type": "textarea", "label": "The checks, if any, that are allowed before I get into bed, agreed with my clinician:"}, {"id": "f4", "type": "textarea", "label": "Nightly log: how many turns it took, and how long until sleep:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: what changed in the number of turns and the strength of the urge:"}]'::jsonb, array['OCD', 'turning the mind', 'uncertainty']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('not-sure-shrug-puppet-craft', 'Not Sure Shrug Puppet Craft', 'kids'::resource_kind, 'A puppet craft in which a child builds a character whose only answer is a shrug, to practice not knowing for sure.', 'Use it to make ''maybe'' and ''not sure'' playful for a child who demands certainty, with the parent asking the questions.', array['Children']::text[], '25 minutes', 'A child caught in ''are you sure'' questions needs a friend who is happily unsure. The child builds a paper bag puppet whose arms are on a string so it can shrug, and gives it a name. The parent asks the puppet the kinds of questions the child usually asks (is the door locked, will it rain, are you sure), and the puppet shrugs and says its line: ''Maybe! Let''s find out later.'' Then the child takes a turn asking. Send it home with a plan for when it comes out. Watch for the child who makes the puppet give certain answers; gently remind them of its one rule.', '[{"id": "f0", "type": "textarea", "label": "My puppet''s name and what it looks like (draw it):"}, {"id": "f1", "type": "textarea", "label": "The questions my grown-up asked it, and how it felt to hear it shrug:"}, {"id": "f2", "type": "textarea", "label": "Its line, in my own words:"}, {"id": "f3", "type": "textarea", "label": "A question I asked it myself:"}, {"id": "f4", "type": "textarea", "label": "When my puppet will come out at home:"}]'::jsonb, array['OCD', 'children', 'uncertainty']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('running-in-place-breathless-on-purpose-log-sheet', 'Running in Place Breathless on Purpose Log Sheet', 'worksheet'::resource_kind, 'A log for a planned bout of running in place to bring on breathlessness and watch it pass.', 'Use it to give a client a repeatable in-session exercise that produces a feared sensation on purpose, with ratings before and after.', array['Adults', 'Teens']::text[], 'Ten minutes in session, then at home if agreed', 'A pounding heart and short breath are the sensations many clients fear most, and running in place for a minute produces both on demand. The log asks for the prediction (what the sensation will mean, how bad it will get), the sensation ratings at the end of the minute and every minute after, and what the client noticed as it faded. Do the first round in session, and set the home rounds yourself. A client with a heart or breathing condition needs their doctor''s okay first. Watch for the client who stops at thirty seconds; note the stopping and the thought that caused it.', '[{"id": "f0", "type": "textarea", "label": "My prediction: what the breathlessness will mean, and how bad it will get (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "How long I ran, and the sensation ratings at the end and at each minute after:"}, {"id": "f2", "type": "textarea", "label": "What I noticed as the sensations faded, and how long that took:"}, {"id": "f3", "type": "textarea", "label": "The thought that showed up at the peak, and what I did with it:"}, {"id": "f4", "type": "textarea", "label": "What this round tells me about the sensation and about my prediction:"}, {"id": "f5", "type": "textarea", "label": "The next round: when, how long, and what I will try to notice:"}]'::jsonb, array['panic attacks', 'interoceptive', 'sensations']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('yawning-means-i-cannot-get-enough-air-fact-check-sheet', 'Yawning Means I Cannot Get Enough Air Fact Check Sheet', 'cbt'::resource_kind, 'A fact check for the belief that yawning or sighing during a surge means the client is running out of air.', 'Use it to reinterpret a body sign that fuels panic and to compare the belief against what the body is actually doing.', array['Adults', 'Teens']::text[], '15 minutes', 'During a surge, clients yawn and sigh and read it as suffocation beginning. The sheet gathers the belief, what the client knows about why bodies yawn and sigh (reset of breathing rhythm, tiredness, a response to fast shallow breathing), the evidence from past surges (how many ended in actual lack of air: none), and a replacement sentence. It is a thinking sheet, not medical advice; a client with breathing conditions talks to their doctor. Watch for the client who starts monitoring every breath after reading this.', '[{"id": "f0", "type": "textarea", "label": "The belief about yawning or sighing during a surge, in its exact words:"}, {"id": "f1", "type": "textarea", "label": "What I know about why bodies yawn and sigh, in plain words:"}, {"id": "f2", "type": "textarea", "label": "How many surges I have had, and how many ended with me actually unable to get air:"}, {"id": "f3", "type": "textarea", "label": "What my breathing was doing just before the yawns (fast, shallow, held):"}, {"id": "f4", "type": "textarea", "label": "A sentence about yawning I could believe at least halfway:"}, {"id": "f5", "type": "textarea", "label": "What I will do with my attention the next time I yawn during a surge:"}]'::jsonb, array['panic attacks', 'fact check', 'sensations']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('panic-as-a-fire-drill-not-a-fire-page', 'Panic as a Fire Drill Not a Fire Page', 'act'::resource_kind, 'An acceptance metaphor for a surge as a drill: loud, disruptive, practiced, and not an actual emergency.', 'Use it to help a client meet a surge as a rehearsal they can walk through rather than an event to escape.', array['Adults', 'Teens']::text[], '15 minutes', 'Everyone knows a fire drill: the alarm is real, the lights flash, and everyone walks out calmly because they know it is a drill. The page invites the client to treat a surge the same way: the body''s alarm is real and loud, and the client can walk through the familiar steps (slow the exhale, keep doing what they were doing, let it run) without searching for the fire. It does not ask the client to like the alarm. Watch for the client who tries to prove it is a drill; the practice is walking through it either way.', '[{"id": "f0", "type": "textarea", "label": "What my body''s alarm sounds like when a surge starts:"}, {"id": "f1", "type": "textarea", "label": "What I do when I believe it is a fire: the escapes, the checks, the calls:"}, {"id": "f2", "type": "textarea", "label": "What a calm walk-through would look like for me: the steps, in order:"}, {"id": "f3", "type": "textarea", "label": "The sentence I will say as the alarm starts (''drill, not fire; walk, do not run''):"}, {"id": "f4", "type": "textarea", "label": "The next drill: what I did, and how the alarm changed as I walked through it:"}]'::jsonb, array['panic attacks', 'acceptance', 'metaphor']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('paced-breathing-in-the-back-of-the-crowded-bus-card', 'Paced Breathing in the Back of the Crowded Bus Card', 'dbt'::resource_kind, 'A paced breathing card for standing room on public transit, when the doors are closed and the surge starts.', 'Use it to give a client a breathing practice tuned to a place they cannot leave for a few minutes.', array['Adults', 'Teens']::text[], 'Five minutes, then the next ride', 'A crowded bus or train between stops is a trap for a client prone to surges: no exit, no seat, other bodies close. Paced breathing is the skill that works standing up with a hand on a pole: a four-count in, a six-count out, eyes on a fixed point, counting stops rather than minutes. The card asks the client to rehearse the count at home, name the fixed point they will use, and decide the stop at which they will reassess rather than bolt. Watch for the client who breathes fast and deep; it is the slow exhale that matters.', '[{"id": "f0", "type": "textarea", "label": "The ride I take that sets this off, and where in the ride the surge usually starts:"}, {"id": "f1", "type": "textarea", "label": "My count: how long in, how long out, and where I will look while I count:"}, {"id": "f2", "type": "textarea", "label": "What I will say to myself as the doors close:"}, {"id": "f3", "type": "textarea", "label": "The stop at which I will reassess, instead of getting off at the next one:"}, {"id": "f4", "type": "textarea", "label": "After the ride: how many breath cycles I did, and what the surge did across the stops:"}]'::jsonb, array['panic attacks', 'paced breathing', 'core DBT']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('straw-breathing-relay-sensation-game', 'Straw Breathing Relay Sensation Game', 'game'::resource_kind, 'A relay in which players breathe through a straw for twenty seconds, pass it on, and rate the sensations.', 'Use it to let a group produce a feared sensation together, see it pass, and compare notes without anyone being singled out.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Rules: players sit in a circle, each with their own straw. On the leader''s signal, the first player breathes only through the straw for twenty seconds, then says one word for the sensation and taps the next player. After everyone has gone, round two is thirty seconds, with a rating from 0 to 100 before and after. Debrief: what the sensations were, how long they lasted after the straw came out, and what the group noticed about predictions versus reality. A member with a breathing condition watches and times. Watch for the member who holds their breath instead; coach the slow in and out.', '[{"id": "f0", "type": "textarea", "label": "My one word for the sensation after round one:"}, {"id": "f1", "type": "textarea", "label": "My rating before and after round two, and how long the feeling lasted once I stopped:"}, {"id": "f2", "type": "textarea", "label": "What I predicted would happen, and what did:"}, {"id": "f3", "type": "textarea", "label": "What I noticed watching others go through it:"}, {"id": "f4", "type": "textarea", "label": "What this tells me about my own body''s air sensations:"}]'::jsonb, array['panic attacks', 'group', 'interoceptive']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('grandparents-spoiling-rules-conversation-prep-sheet', 'Grandparents Spoiling Rules Conversation Prep Sheet', 'worksheet'::resource_kind, 'A prep sheet for the talk with grandparents who override the house rules on sweets, screens and bedtime.', 'Use it to help a parent decide which rules matter enough to raise, and to script a warm, clear ask.', array['Adults']::text[], '20 minutes', 'Grandparents who spoil are a gift and a headache, and a parent who feels undermined often either says nothing and seethes or says too much and starts a family rift. The sheet sorts the rules into ones that matter (safety, sleep before school) and ones that can bend at Grandma''s house, asks what the grandparents are getting out of the spoiling (closeness, making up for their own parenting), and scripts an ask that leads with appreciation. Watch for the parent who wants the grandparents to follow every rule; pick two.', '[{"id": "f0", "type": "textarea", "label": "What the grandparents do that bothers me, listed plainly:"}, {"id": "f1", "type": "textarea", "label": "The rules that truly matter to me (safety, sleep, school nights), and the ones that can bend at their house:"}, {"id": "f2", "type": "textarea", "label": "What I think the grandparents get from spoiling, and how I can honor that:"}, {"id": "f3", "type": "textarea", "label": "The ask, in two or three sentences, starting with what I appreciate:"}, {"id": "f4", "type": "textarea", "label": "What I will do if they agree and slip anyway:"}, {"id": "f5", "type": "textarea", "label": "After the talk: what I said, how it landed, and what I would change:"}]'::jsonb, array['parenting', 'family', 'communication']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('my-teen-s-eye-roll-means-contempt-thought-record', 'My Teen''s Eye Roll Means Contempt Thought Record', 'cbt'::resource_kind, 'A thought record for the parent who reads a teenager''s eye roll as hatred and reacts to the hatred.', 'Use it to separate what a teen''s face did from what the parent decided it meant, before the next exchange.', array['Adults']::text[], '15 minutes', 'The eye roll lands like a slap and the parent responds to the slap, not the gesture. The record asks for the moment, the thought (she despises me, I have lost him), the heat it produced and what the parent did next, then for other readings of an eye roll from a teenager (embarrassment, a reflex, wanting to look cool, agreeing but unable to show it) and what the parent would want their response to be next time. Watch for the parent who treats the eye roll as the real problem; it is the reading that is costing them.', '[{"id": "f0", "type": "textarea", "label": "What my teen did, described as a camera would see it:"}, {"id": "f1", "type": "textarea", "label": "What I decided it meant, in its exact words:"}, {"id": "f2", "type": "textarea", "label": "How hot I got, 0 to 10, and what I did next:"}, {"id": "f3", "type": "textarea", "label": "Other things an eye roll can mean from a teenager (list at least four):"}, {"id": "f4", "type": "textarea", "label": "What I know about my teen that fits a kinder reading:"}, {"id": "f5", "type": "textarea", "label": "What I want my response to look like the next time, and the sentence I will use or not use:"}]'::jsonb, array['parenting', 'mind reading', 'thought record']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('values-when-my-kid-says-i-hate-you-page', 'Values When My Kid Says I Hate You Page', 'act'::resource_kind, 'A values page for the moment a child says the worst thing, when the parent''s mind offers hurt and retaliation.', 'Use it to help a parent choose a response from their parenting values rather than from the sting.', array['Adults']::text[], '20 minutes', '''I hate you'' is designed to land, and it does. The page asks the parent to write what their mind offered in that moment (hurt, anger, the urge to say something back), the value they most want to parent from (steadiness, warmth, holding a limit), what that value would say in that moment, and whether they are willing to feel the sting and say it anyway. It never asks the parent to not be hurt. Watch for the parent who wants a line that stops the child from saying it; the page is about who the parent is when it is said.', '[{"id": "f0", "type": "textarea", "label": "The moment, and the exact words my child used:"}, {"id": "f1", "type": "textarea", "label": "What my mind offered me in the seconds after: thoughts, urges, the comeback:"}, {"id": "f2", "type": "textarea", "label": "The value I most want to parent from in hard moments, in my own words:"}, {"id": "f3", "type": "textarea", "label": "What that value would do and say in that moment:"}, {"id": "f4", "type": "textarea", "label": "Am I willing to feel the sting and act from the value anyway? What would that cost and what would it give?"}, {"id": "f5", "type": "textarea", "label": "The next time: what I did, and how it sat with me an hour later:"}]'::jsonb, array['parenting', 'values', 'willingness']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('validation-for-the-teen-who-did-not-make-the-team-card', 'Validation for the Teen Who Did Not Make the Team Card', 'dbt'::resource_kind, 'A validation card for parents when a teenager is cut from a team, a cast or a club and wants no advice.', 'Use it to give a parent the first three things to say and the three things to hold back.', array['Adults']::text[], '15 minutes', 'A teen who did not make the team needs their disappointment taken seriously before anything else, and the parent''s instinct, to fix, to blame the coach, to point at next year, lands as dismissal. The card walks the validation levels: pay attention, reflect back, read what is unsaid, make sense of the feeling given the facts, treat it as understandable for anyone. It asks the parent to write what they will say and what they will not say in the first ten minutes. Watch for the parent whose own disappointment is louder than the teen''s.', '[{"id": "f0", "type": "textarea", "label": "What happened, and how my teen told me (or did not):"}, {"id": "f1", "type": "textarea", "label": "What I wanted to say first: the fix, the blame, the silver lining:"}, {"id": "f2", "type": "textarea", "label": "Three sentences I will say instead that show I heard them:"}, {"id": "f3", "type": "textarea", "label": "Three things I will not say in the first ten minutes:"}, {"id": "f4", "type": "textarea", "label": "My own feelings about it, and who I will talk to about those instead of my teen:"}, {"id": "f5", "type": "textarea", "label": "After: what I said, what my teen did, and whether they came back to talk later:"}]'::jsonb, array['parenting', 'validation', 'core DBT']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('family-meeting-talking-spoon-craft', 'Family Meeting Talking Spoon Craft', 'kids'::resource_kind, 'A craft in which the family decorates a wooden spoon that gives the holder the floor at family meetings.', 'Use it to help a family practice one voice at a time, with a child in charge of the rule, and the parent modeling waiting.', array['Children']::text[], '20 minutes to make, then weekly', 'A wooden spoon wrapped in ribbon and stickers becomes the family''s talking spoon: whoever holds it speaks, everyone else listens, and it passes when the holder is done. The child decorates it and becomes its keeper, which gives them real authority in a ritual where they usually have none. Hold a short first meeting about something small (what to have for Friday dinner). The parent waits for the spoon just like everyone else, including when interrupted by a sibling. Watch for the parent who grabs the spoon to settle an argument; that teaches the opposite lesson.', '[{"id": "f0", "type": "textarea", "label": "What our talking spoon looks like (draw it):"}, {"id": "f1", "type": "textarea", "label": "The rules of the spoon, in my words:"}, {"id": "f2", "type": "textarea", "label": "What our first family meeting was about:"}, {"id": "f3", "type": "textarea", "label": "What it was like to hold it and have everyone wait for me:"}, {"id": "f4", "type": "textarea", "label": "What it was like to wait for it when I had something to say:"}]'::jsonb, array['parenting', 'children', 'communication']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('baby-shower-thank-you-notes-pacing-sheet', 'Baby Shower Thank You Notes Pacing Sheet', 'worksheet'::resource_kind, 'A pacing sheet for the pile of thank you notes that sits unwritten while a new parent feels worse each week.', 'Use it to turn a guilt-laden task into three or four tiny sittings with permission to keep the notes short.', array['Adults']::text[], 'Ten minutes, three times a week', 'The gifts have been opened, the baby has arrived, and the notes sit in a stack that grows heavier with every week of guilt. The sheet asks for the honest count, a two-line template, a stack of five per sitting during a nap or a feed, and a line for the ones that will not get written at all, with permission. It also asks what the guilt is saying about the client as a parent, which is usually the bigger thing. Watch for the client who insists each note be personal and long; that standard is why the stack exists.', '[{"id": "f0", "type": "textarea", "label": "How many notes are waiting, and how long they have waited:"}, {"id": "f1", "type": "textarea", "label": "My two-line template, written once:"}, {"id": "f2", "type": "textarea", "label": "The sittings: five notes each, at which nap or feed, on which days:"}, {"id": "f3", "type": "textarea", "label": "The ones I will let go of entirely, and who I could ask to text a thank you instead:"}, {"id": "f4", "type": "textarea", "label": "What the guilt about these notes says about me as a parent, in its exact words:"}, {"id": "f5", "type": "textarea", "label": "After: how many I sent, and what the pile looked like when it was gone:"}]'::jsonb, array['perinatal and postpartum', 'pacing', 'guilt']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('pumping-or-formula-means-i-failed-thought-record', 'Pumping or Formula Means I Failed Thought Record', 'cbt'::resource_kind, 'A thought record for the shame a new parent attaches to how the baby is fed when the plan changed.', 'Use it to examine a failure thought about feeding without taking any position on the feeding itself.', array['Adults']::text[], '20 minutes', 'A feeding plan that changed, by choice or by necessity, becomes for many new parents a verdict on themselves. The record asks for the thought in its exact words, the feeling and its intensity, what ''failed'' would have to mean for it to be true, the evidence that the baby is being fed and cared for, and what the client would say to a friend who fed their baby this way. The clinician does not weigh in on feeding. Watch for the client who wants the record to settle whether they made the right choice; that is not its job.', '[{"id": "f0", "type": "textarea", "label": "What changed about feeding, in plain facts:"}, {"id": "f1", "type": "textarea", "label": "The thought about myself, in its exact words, and the feeling with it (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "What ''failed'' would have to mean for the thought to be true:"}, {"id": "f3", "type": "textarea", "label": "The evidence that my baby is fed, held and cared for:"}, {"id": "f4", "type": "textarea", "label": "What I would say to a friend who fed her baby exactly this way:"}, {"id": "f5", "type": "textarea", "label": "A sentence about how my baby is fed that I could say without flinching:"}]'::jsonb, array['perinatal and postpartum', 'thought record', 'self-criticism']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('values-when-the-nursery-is-not-finished-page', 'Values When the Nursery Is Not Finished Page', 'act'::resource_kind, 'A values page for the expecting or new parent whose mind says the unfinished room means they are unready.', 'Use it to separate the picture of readiness from the values the client will actually parent from.', array['Adults']::text[], '15 minutes', 'The nursery is half painted, the crib is in a box, and the mind says a prepared parent would have finished. The page asks what the finished room has come to stand for, what the client actually wants to give this child in the first weeks (none of which is paint), the value under that, and one small act from the value this week that is not about the room. It does not say the room does not matter. Watch for the client whose partner is the one saying the room should be done; that is a couples conversation.', '[{"id": "f0", "type": "textarea", "label": "What the unfinished room has come to mean about me:"}, {"id": "f1", "type": "textarea", "label": "What I actually want to give this baby in the first weeks, listed plainly:"}, {"id": "f2", "type": "textarea", "label": "The value under that list, in one or two words of my own:"}, {"id": "f3", "type": "textarea", "label": "One small act this week from that value that has nothing to do with the room:"}, {"id": "f4", "type": "textarea", "label": "What I will say to my mind the next time it walks me into the nursery to show me what is missing:"}]'::jsonb, array['perinatal and postpartum', 'values', 'defusion']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('dear-man-for-the-grandparent-who-keeps-dropping-by-card', 'DEAR MAN for the Grandparent Who Keeps Dropping By Card', 'dbt'::resource_kind, 'A DEAR MAN script for asking a relative to call before visiting the new baby, kindly and clearly.', 'Use it to rehearse a boundary with a well-meaning relative without the client swallowing it or exploding.', array['Adults']::text[], '15 minutes', 'The grandparent who shows up unannounced with a casserole means love and lands as pressure on a parent who has not slept. The card walks DEAR MAN with the client''s own words: describe the visits, express the effect, assert the request (a text an hour before, and some days a no), reinforce what it will mean for the relationship, stay mindful when the relative gets hurt, appear confident even in a bathrobe, and negotiate (a standing Sunday visit instead). Have the client say it aloud. Watch for the client who wants their partner to say it to their own parent; the card works for that too.', '[{"id": "f0", "type": "textarea", "label": "Describe: the visits, in neutral facts (how often, when, how long):"}, {"id": "f1", "type": "textarea", "label": "Express: what the surprise visits do to me, in one sentence that does not blame:"}, {"id": "f2", "type": "textarea", "label": "Assert: the exact request, in one plain sentence:"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what the relative gets if they do this (more relaxed visits, a happier parent):"}, {"id": "f4", "type": "textarea", "label": "Mindful and Appear confident: what I will say when they look hurt, and how I will stand:"}, {"id": "f5", "type": "textarea", "label": "Negotiate: what I could offer instead (a standing visit, a weekly photo, a specific job for them):"}]'::jsonb, array['perinatal and postpartum', 'DEAR MAN', 'boundaries']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('who-gets-up-with-the-sick-baby-rotation-for-new-parents', 'Who Gets Up With the Sick Baby Rotation for New Parents', 'couples'::resource_kind, 'A rotation sheet for the nights when the baby is sick and both parents are already past empty.', 'Use it to set the night plan before the fever, so the hardest nights are not also a negotiation.', array['Couples']::text[], '15 minutes while everyone is well', 'A sick baby turns a tired couple into two exhausted people keeping score at three in the morning. The sheet asks each parent what they can do on no sleep and what they cannot, who takes which block on a sick night and how it swaps for the next one, what counts as an emergency and who calls the doctor, and what each will say to the other at dawn instead of a tally. It also plans the next day: who sleeps in, who calls work. Watch for the parent who always takes the night because they are the one who can hear the baby; put a monitor by the other one''s head.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I can do on no sleep, and what I truly cannot:"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can do on no sleep, and what I truly cannot:"}, {"id": "f2", "type": "textarea", "label": "Sick night blocks: who takes which hours, and how it swaps the next night:"}, {"id": "f3", "type": "textarea", "label": "What counts as calling the doctor or going in, and who makes that call:"}, {"id": "f4", "type": "textarea", "label": "The next morning: who sleeps in, who calls work, who handles the older child if there is one:"}, {"id": "f5", "type": "textarea", "label": "What we will say to each other at dawn instead of counting who did more:"}]'::jsonb, array['perinatal and postpartum', 'couples', 'fairness']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('ordering-first-at-the-restaurant-log-sheet', 'Ordering First at the Restaurant Log Sheet', 'worksheet'::resource_kind, 'A log for small moments of going first, choosing first and speaking first, for a client who always defers.', 'Use it to track and gently increase the times a client takes up ordinary space in a group.', array['Adults', 'Teens']::text[], 'Two weeks', 'A client with little sense of their own worth will wait for everyone else to order, let others pick the movie, and speak last if at all. The log is for the smallest reversals: ordering first, naming a preference before asking others'', taking the chair they want. Each entry records the moment, the body''s reaction, what others actually did, and the thought that showed up. Two weeks usually shows the sky does not fall. Watch for the client who goes first and then apologizes for it; log the apology too.', '[{"id": "f0", "type": "textarea", "label": "Each moment I went first, chose first or spoke first this week: where and with whom:"}, {"id": "f1", "type": "textarea", "label": "What my body did in the second before I did it:"}, {"id": "f2", "type": "textarea", "label": "What the other people actually did (not what I feared):"}, {"id": "f3", "type": "textarea", "label": "The thought that showed up after, in its exact words:"}, {"id": "f4", "type": "textarea", "label": "Any apology I added, and whether it was needed:"}, {"id": "f5", "type": "textarea", "label": "After two weeks: what I notice about going first, and the next small space I will take:"}]'::jsonb, array['self-esteem', 'assertiveness', 'self-monitoring']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('if-i-fail-the-test-i-am-stupid-labeling-sheet', 'If I Fail the Test I Am Stupid Labeling Sheet', 'cbt'::resource_kind, 'A labeling sheet for the leap from one bad grade or missed answer to a verdict on the whole person.', 'Use it to pull the label off the event and to practice describing a result without naming the self.', array['Teens', 'Adults']::text[], '15 minutes', 'A result becomes a name: I failed, so I am stupid. The sheet names the leap (labeling), asks for the event in plain facts, the label, what the label would have to be true of for it to hold (every subject, every day, forever), the evidence against, and a description of the result that does not name the self. It ends with the next concrete step about the test. Watch for the client who accepts the sheet''s logic and keeps the label anyway; ask who first used that word on them.', '[{"id": "f0", "type": "textarea", "label": "What happened, in plain facts: the test, the score, what I missed:"}, {"id": "f1", "type": "textarea", "label": "The label I gave myself, in its exact words:"}, {"id": "f2", "type": "textarea", "label": "For that label to be true, what would have to be true of me in every subject, every day:"}, {"id": "f3", "type": "textarea", "label": "Evidence that does not fit the label, from this month alone:"}, {"id": "f4", "type": "textarea", "label": "A description of the result that uses no name for me:"}, {"id": "f5", "type": "textarea", "label": "The next concrete step about the test itself, and when I will take it:"}]'::jsonb, array['self-esteem', 'labeling', 'thinking traps']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('mind-as-a-bouncer-who-does-not-let-me-in-page', 'Mind as a Bouncer Who Does Not Let Me In Page', 'act'::resource_kind, 'A defusion metaphor for the inner voice that stands at every door and says the client does not belong here.', 'Use it to help a client recognize the bouncer''s lines, hear them as lines, and walk in anyway.', array['Adults', 'Teens']::text[], '20 minutes', 'The bouncer stands at the door of the meeting, the party, the application, and says: not you, not here, who do you think you are. He is loud and he is not the owner. The page asks the client to collect the bouncer''s lines, notice the rooms he guards most fiercely, and practice walking past with the lines still playing. It is not an argument with the bouncer. Watch for the client who wants to earn their way in first; the door was never his to guard.', '[{"id": "f0", "type": "textarea", "label": "The doors my bouncer guards: the rooms, roles and groups he says are not for me:"}, {"id": "f1", "type": "textarea", "label": "His lines, word for word:"}, {"id": "f2", "type": "textarea", "label": "What happens when I turn around at the door, and what it has cost me this year:"}, {"id": "f3", "type": "textarea", "label": "The sentence I will say as I walk past him (''I hear you, and I am going in''):"}, {"id": "f4", "type": "textarea", "label": "One door I walked through this week with the bouncer talking, and what was on the other side:"}]'::jsonb, array['self-esteem', 'defusion', 'metaphor']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('fast-skill-correcting-the-mispronounced-name-card', 'FAST Skill Correcting the Mispronounced Name Card', 'dbt'::resource_kind, 'A FAST card for correcting someone who says the client''s name wrong, instead of letting it go for years.', 'Use it to practice a small act of self-respect with Fair, Apologies, Stick to values and Truthful.', array['Adults', 'Teens']::text[], '15 minutes', 'Letting a name go uncorrected is a small daily surrender many clients make for years. FAST is the skill for self-respect in a request: be Fair to yourself and the other person, no unnecessary Apologies, Stick to your values, be Truthful. The card scripts the correction (my name is said like this), the apology the client will not add, the value it serves, and the plan for the second and third time the person gets it wrong. Watch for the client who corrects once and then answers to the wrong name again to avoid awkwardness.', '[{"id": "f0", "type": "textarea", "label": "Who says my name wrong, how often, and how long I have let it go:"}, {"id": "f1", "type": "textarea", "label": "Fair: a correction that is fair to me and to them, in my words:"}, {"id": "f2", "type": "textarea", "label": "Apologies: the apology I usually add, and the sentence I will say instead:"}, {"id": "f3", "type": "textarea", "label": "Stick to values: the value this serves for me:"}, {"id": "f4", "type": "textarea", "label": "Truthful: what is true about how this has felt, said simply:"}, {"id": "f5", "type": "textarea", "label": "The second and third time they get it wrong: what I will say:"}]'::jsonb, array['self-esteem', 'FAST', 'interpersonal effectiveness']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('yearbook-superlatives-kind-edition-game', 'Yearbook Superlatives Kind Edition Game', 'game'::resource_kind, 'A group game in which members write and award kind, specific superlatives to each other, yearbook style.', 'Use it to let a group practice giving and receiving specific recognition for who someone is, not how they look.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Rules: each member writes one superlative for every other member on a slip (Most Likely to Notice When Someone Is Quiet, Best at Asking the Real Question), nothing about appearance, nothing sarcastic. Slips go in a box; the leader reads each one aloud and the room guesses who it is for before the name is revealed. Each member keeps their slips. Debrief: what it was like to hear yours, which one surprised you, and what you did with your face while it was read. Watch for the member who jokes through theirs; ask them to read one back aloud.', '[{"id": "f0", "type": "textarea", "label": "The superlatives I wrote for others, and which was hardest to write:"}, {"id": "f1", "type": "textarea", "label": "The superlatives I received:"}, {"id": "f2", "type": "textarea", "label": "The one that surprised me, and why:"}, {"id": "f3", "type": "textarea", "label": "What I did with my face and body while mine were read:"}, {"id": "f4", "type": "textarea", "label": "One I will keep somewhere I will see it this week:"}]'::jsonb, array['self-esteem', 'group', 'game']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('returning-to-the-gym-class-after-missing-weeks-steps-sheet', 'Returning to the Gym Class After Missing Weeks Steps Sheet', 'worksheet'::resource_kind, 'A step plan for walking back into a class, group or club after a long absence the client fears was noticed.', 'Use it to break a dreaded return into steps and to test the belief that everyone noticed and judged the gap.', array['Adults', 'Teens']::text[], '20 minutes, then the return', 'Missing a few weeks of a class turns into never going back, because the client is sure the return will involve questions and judgment. The sheet writes the prediction, plans the steps (which session, where to stand, the one-line answer to ''where have you been'', who to nod at), and asks the client to record what actually happened. Most returns involve no questions at all, which is its own lesson. Watch for the client who plans the return for a week when they will have a cold; that is the avoidance planning.', '[{"id": "f0", "type": "textarea", "label": "What I have been missing, how long, and the reason I give others versus the real one:"}, {"id": "f1", "type": "textarea", "label": "What I predict will happen when I walk back in:"}, {"id": "f2", "type": "textarea", "label": "My one-line answer if anyone asks where I have been:"}, {"id": "f3", "type": "textarea", "label": "The steps: which session, when I arrive, where I stand, who I nod to:"}, {"id": "f4", "type": "textarea", "label": "What actually happened: who said what, and how long the discomfort lasted:"}, {"id": "f5", "type": "textarea", "label": "What this tells me about returns, and the next one I might make:"}]'::jsonb, array['social anxiety', 'avoidance', 'planning']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('being-asked-a-question-in-the-elevator-thought-record', 'Being Asked a Question in the Elevator Thought Record', 'cbt'::resource_kind, 'A thought record for the small-talk question in a confined space that the client replays for the rest of the day.', 'Use it to catch post-event rumination after a brief exchange and to weigh the mind''s review against what happened.', array['Adults', 'Teens']::text[], '15 minutes', 'A neighbor asks ''any plans this weekend'' between the fourth and the lobby, and the client''s answer, delivered a beat late, gets reviewed for hours. The record asks for the exchange as a transcript, the thought about how it went, the review''s specific charges (I sounded weird, they regretted asking), the evidence from the other person''s actual behavior, and how a stranger would have seen the twenty seconds. Watch for the client who rewrites the perfect answer afterward; that is rehearsal for the next replay.', '[{"id": "f0", "type": "textarea", "label": "The exchange, as close to a transcript as I can manage:"}, {"id": "f1", "type": "textarea", "label": "The thought about how it went, in its exact words:"}, {"id": "f2", "type": "textarea", "label": "The specific charges my mind made afterward, and how long I spent on them:"}, {"id": "f3", "type": "textarea", "label": "What the other person actually did and said, with no interpretation:"}, {"id": "f4", "type": "textarea", "label": "How a stranger watching those twenty seconds would have described them:"}, {"id": "f5", "type": "textarea", "label": "A sentence about the exchange I can leave it with, and what I will do the next time my mind reopens it:"}]'::jsonb, array['social anxiety', 'rumination', 'thought record']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('taking-the-blank-mind-to-the-introduction-round-page', 'Taking the Blank Mind to the Introduction Round Page', 'act'::resource_kind, 'A willingness page for the moment the group goes around the circle and the client''s mind goes empty.', 'Use it to help a client carry the blank, racing feeling into the round and speak anyway, briefly.', array['Adults', 'Teens']::text[], '15 minutes before a group', 'The introduction round is a small torture for many clients: everyone will speak, the turn is coming, and the mind empties. The page asks the client to describe the blank as sensation and thought, to decide the two sentences they will say regardless (a name and one plain fact), to notice what the mind offers while they wait (everyone else is better at this), and whether they are willing to have the blank and the heartbeat and say the two sentences anyway. Watch for the client who rehearses so hard they do not hear anyone else; the round is also for listening.', '[{"id": "f0", "type": "textarea", "label": "What happens in my body and mind as the round comes toward me:"}, {"id": "f1", "type": "textarea", "label": "The two sentences I will say regardless of how I feel:"}, {"id": "f2", "type": "textarea", "label": "What my mind usually offers while I wait for my turn:"}, {"id": "f3", "type": "textarea", "label": "Am I willing to have the blank and the pounding and say my two sentences? What does willing look like in my posture?"}, {"id": "f4", "type": "textarea", "label": "After the round: what I said, what the blank did once I spoke, and one thing I heard someone else say:"}]'::jsonb, array['social anxiety', 'willingness', 'present moment']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('opposite-action-to-texting-instead-of-calling-card', 'Opposite Action to Texting Instead of Calling Card', 'dbt'::resource_kind, 'An opposite action card for the reflex of texting when a call would be quicker, kinder or necessary.', 'Use it to help a client act opposite to social avoidance with one planned call this week.', array['Adults', 'Teens']::text[], 'One week', 'Texting lets a client avoid the voice, the pause and the unplanned question, and the avoidance keeps the fear of calls alive. Opposite action here is a call made all the way: standing up, no script longer than three lines, no hanging up at the first ring. The card asks which message this week should be a call, what the fear predicts, the three-line plan, and what actually happened. Choose a call with a reason (a doctor''s office, a friend''s birthday). Watch for the client who leaves a voicemail and counts it; a real conversation is the opposite action.', '[{"id": "f0", "type": "textarea", "label": "The message this week that should be a call, and why:"}, {"id": "f1", "type": "textarea", "label": "What the fear predicts will happen on the call:"}, {"id": "f2", "type": "textarea", "label": "My three-line plan for the call, and the time I will make it:"}, {"id": "f3", "type": "textarea", "label": "The urge to text instead: how strong, 0 to 100, as I dial:"}, {"id": "f4", "type": "textarea", "label": "What actually happened, how long it took, and the urge rating afterward:"}, {"id": "f5", "type": "textarea", "label": "The next call I will make, and whether it needs a plan at all:"}]'::jsonb, array['social anxiety', 'opposite action', 'core DBT']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('mingle-bell-switch-partners-small-talk-game', 'Mingle Bell Switch Partners Small Talk Game', 'game'::resource_kind, 'A party-style game in which a bell rings every ninety seconds and everyone finds a new partner and a new question.', 'Use it to give a group many short, low-stakes conversations in a row, with endings built in.', array['Groups', 'Teens', 'Adults']::text[], '20 minutes', 'Rules: everyone stands. The leader rings a bell; players pair with the nearest person and draw a question card (what did you eat for breakfast, what is one thing you are good at that nobody knows). Ninety seconds later the bell rings again, pairs say ''good talking to you'' and find someone new. Six rounds. Debrief: which round was hardest, what happened to the nerves across rounds, and what it was like to have a built-in ending. Watch for the member who keeps the same partner; the bell means move.', '[{"id": "f0", "type": "textarea", "label": "Round one: what my nerves did, 0 to 100:"}, {"id": "f1", "type": "textarea", "label": "Round six: what my nerves did, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "The question that was easiest, and the one that was hardest to answer:"}, {"id": "f3", "type": "textarea", "label": "What it was like to have the bell end the conversation for me:"}, {"id": "f4", "type": "textarea", "label": "One thing I learned about someone, and one line I can use to end a conversation outside this room:"}]'::jsonb, array['social anxiety', 'group', 'social skills']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('donating-their-clothes-one-bag-at-a-time-pacing-sheet', 'Donating Their Clothes One Bag at a Time Pacing Sheet', 'worksheet'::resource_kind, 'A pacing sheet for the closet, one bag per sitting, with a keep pile and permission to stop.', 'Use it to help a grieving client approach the clothes at their own pace, deciding what to keep and when to pause.', array['Adults']::text[], 'One bag per sitting, as the client chooses', 'The closet full of someone''s clothes is often the last thing touched, and the client gets advice from everyone about when. The sheet puts the client in charge: one bag per sitting, a keep pile with no limit, a sitting-ended signal (tears are allowed, exhaustion ends it), who will be in the house, and where the bags go. It asks what they will do with the hour after. Nothing on it says when this should be finished. Watch for the client who does the whole closet in one night to get it over with and regrets it by morning.', '[{"id": "f0", "type": "textarea", "label": "When I will do the first bag, and who will be in the house or on the phone:"}, {"id": "f1", "type": "textarea", "label": "The keep pile: things I already know I want, and permission to add more:"}, {"id": "f2", "type": "textarea", "label": "The signal that ends a sitting (a feeling, a time, a number of items):"}, {"id": "f3", "type": "textarea", "label": "Where the bags will go, and who will take them if I do not want to:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the hour after each sitting:"}, {"id": "f5", "type": "textarea", "label": "After the first bag: what I kept, what I let go, and how I am:"}]'::jsonb, array['grief and loss', 'pacing', 'support']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('being-angry-at-them-means-i-did-not-love-them-thought-record', 'Being Angry at Them Means I Did Not Love Them Thought Record', 'cbt'::resource_kind, 'A thought record for the guilt a grieving client feels about anger at the person who died.', 'Use it to let anger at the dead sit next to love without the client having to choose one.', array['Adults', 'Teens']::text[], '20 minutes in session', 'Anger at someone who died, for leaving, for the drinking, for the unfinished business, is common and feels forbidden, and the thought underneath it is that anger cancels love. The record asks for the anger in plain words, the guilt thought, what the client believes anger proves, the evidence from their own living relationships that anger and love coexist, and a both-and sentence. Do it in session; the anger needs a witness. Watch for the client who wants to resolve the anger today; it is allowed to stay a while.', '[{"id": "f0", "type": "textarea", "label": "What I am angry at them about, in plain words:"}, {"id": "f1", "type": "textarea", "label": "The thought about what the anger means about my love, in its exact words:"}, {"id": "f2", "type": "textarea", "label": "The feeling that comes with that thought, and its strength:"}, {"id": "f3", "type": "textarea", "label": "People alive in my life I have been furious with and still loved; what that tells me:"}, {"id": "f4", "type": "textarea", "label": "A both-and sentence: ''I am angry that... and I love...'':"}, {"id": "f5", "type": "textarea", "label": "What I want to do with the anger this month: write it, say it here, leave it on the sheet:"}]'::jsonb, array['grief and loss', 'guilt', 'thought record']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('grief-as-a-room-i-add-to-the-house-page', 'Grief as a Room I Add to the House Page', 'act'::resource_kind, 'An acceptance metaphor for grief as a new room in the house of the client''s life, not a demolition.', 'Use it to help a client see grief as something the life grows around rather than something to shrink.', array['Adults', 'Teens']::text[], '20 minutes', 'The common picture is that grief shrinks over time. For many clients it does not; the life grows around it. The page offers a different picture: grief is a room added to the house. It is always there, the client can go in and sit, and the rest of the house is still the house. The page asks what is in the room, how often the client visits now, what the other rooms hold, and what it would mean to stop trying to tear the room down. Watch for the client who lives in the room; the page also asks about the door.', '[{"id": "f0", "type": "textarea", "label": "What is in the room: the objects, the sounds, the time of day it is in there:"}, {"id": "f1", "type": "textarea", "label": "How often I go in now, and how long I stay:"}, {"id": "f2", "type": "textarea", "label": "The other rooms of my house, and which ones I have not been in since:"}, {"id": "f3", "type": "textarea", "label": "What I have been trying to do to the room, and what it has cost:"}, {"id": "f4", "type": "textarea", "label": "The door: what it would be like to leave it open and walk through the rest of the house:"}]'::jsonb, array['grief and loss', 'acceptance', 'metaphor']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('observe-the-urge-to-set-their-place-at-the-table-card', 'Observe the Urge to Set Their Place at the Table Card', 'dbt'::resource_kind, 'An observe card for the reflexes of the first weeks: setting their place, buying their brand, saving them a seat.', 'Use it to help a client notice these urges with tenderness instead of shame, and decide each time what to do with them.', array['Adults']::text[], 'Two weeks', 'The hand reaches for the second plate before the mind remembers. The reflexes of a shared life outlive the person, and clients feel foolish about them. The card asks the client to observe each one as it happens (the urge, where it lives in the body, what the hands did) and to describe it without judgment. Some days the client sets the place anyway and that is allowed. Watch for the client who tries to stop the reflexes by force; they fade on their own schedule.', '[{"id": "f0", "type": "textarea", "label": "The reflexes I have noticed: setting a place, buying their brand, saving a seat, waiting for the car:"}, {"id": "f1", "type": "textarea", "label": "Each time this week: the urge, where it lived in my body, and what my hands did:"}, {"id": "f2", "type": "textarea", "label": "A description of one, without a single judging word:"}, {"id": "f3", "type": "textarea", "label": "What I chose to do with it that day (follow it, let it pass, something else), and how that was:"}, {"id": "f4", "type": "textarea", "label": "After two weeks: what I notice about how often they come and how they feel:"}]'::jsonb, array['grief and loss', 'observe', 'mindfulness']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('star-jar-wishes-for-someone-who-died-craft', 'Star Jar Wishes for Someone Who Died Craft', 'kids'::resource_kind, 'A craft in which a child folds paper stars with things they wish they could tell the person and keeps them in a jar.', 'Use it to give a grieving child a place to put the unsaid things, with a parent adding stars of their own.', array['Children']::text[], '25 minutes, then as needed', 'A child who has lost someone often has things to say with nowhere to put them. The child decorates a jar, and together with the clinician folds strips of paper into small stars, writing or drawing on each strip something they wish they could tell the person: news from school, a question, something they are sorry about, something funny. The parent folds stars too and reads one aloud. The jar goes home with a plan to add a star whenever one is needed and to read some together at times the child chooses. Watch for the child who wants to fill the jar today; three or four stars is plenty.', '[{"id": "f0", "type": "textarea", "label": "What my jar looks like (draw it):"}, {"id": "f1", "type": "textarea", "label": "The stars I made today, and what I put on them (as much as I want to share):"}, {"id": "f2", "type": "textarea", "label": "The star my grown-up made and read to me:"}, {"id": "f3", "type": "textarea", "label": "When I will add a new star, and where the jar lives:"}, {"id": "f4", "type": "textarea", "label": "Who I would like to read the stars with, and when:"}]'::jsonb, array['grief and loss', 'children', 'craft']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('friend-who-never-asks-about-me-conversation-prep-sheet', 'Friend Who Never Asks About Me Conversation Prep Sheet', 'worksheet'::resource_kind, 'A prep sheet for raising, with a friend, that every conversation is about them and never about the client.', 'Use it to help a client decide whether to say something, what to say, and what they want from the friendship afterward.', array['Adults', 'Teens']::text[], '20 minutes', 'The friend talks for an hour and hangs up without one question, and the client leaves drained and unsure whether to say anything. The sheet asks for the pattern in facts (the last three calls), what the client has done so far (nothing, hinting, pulling away), what they want from the friendship if it could change, a two-sentence opener that is honest and not an indictment, and what they will do if the friend cannot hear it. Watch for the client who wants the friend to notice without being told; the sheet is for saying it.', '[{"id": "f0", "type": "textarea", "label": "The last three conversations: roughly how much was about them, and what I shared, if anything:"}, {"id": "f1", "type": "textarea", "label": "What I have done so far: nothing, hinting, going quiet, pulling back:"}, {"id": "f2", "type": "textarea", "label": "What I want from this friendship if it could change, honestly:"}, {"id": "f3", "type": "textarea", "label": "My two-sentence opener: honest, specific, not a verdict on them:"}, {"id": "f4", "type": "textarea", "label": "What I will do if they get defensive or do not hear it:"}, {"id": "f5", "type": "textarea", "label": "After the talk, or after deciding not to have it: what I chose and how it sits:"}]'::jsonb, array['relationship issues', 'friendship', 'assertiveness']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('they-did-not-say-thank-you-so-they-are-ungrateful-record', 'They Did Not Say Thank You So They Are Ungrateful Record', 'cbt'::resource_kind, 'A thought record for the missed thank you that turns into a verdict on a person''s character.', 'Use it to catch the leap from one omission to a global judgment and to weigh the ordinary explanations.', array['Adults', 'Teens']::text[], '15 minutes', 'The client did a favor, the thank you did not come, and within an hour the person is ungrateful and selfish. The record asks for the favor and the omission in plain facts, the global verdict, how sure the client is, the ordinary explanations for a missed thank you (distraction, assuming it was understood, a bad week, a different family style), and the evidence from the person''s history. It ends with what the client actually wants (to be thanked, to be seen) and whether to ask. Watch for the client with a ledger of unthanked favors; that is a conversation about asking.', '[{"id": "f0", "type": "textarea", "label": "The favor, and what did and did not happen afterward, in plain facts:"}, {"id": "f1", "type": "textarea", "label": "The verdict on their character, in its exact words, and how sure I am (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "Ordinary explanations for a missed thank you (list at least four):"}, {"id": "f3", "type": "textarea", "label": "This person''s history with me: times they have shown gratitude or care:"}, {"id": "f4", "type": "textarea", "label": "What I actually wanted from them, and whether I can ask for it plainly:"}, {"id": "f5", "type": "textarea", "label": "A sentence about the missed thank you that is accurate and not a verdict:"}]'::jsonb, array['relationship issues', 'overgeneralization', 'thought record']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('values-when-i-am-the-one-who-was-wrong-page', 'Values When I Am the One Who Was Wrong Page', 'act'::resource_kind, 'A values page for the moment a client realizes they were wrong in a fight and the mind offers defenses instead.', 'Use it to help a client act from their relationship values when admitting fault is the costly move.', array['Adults', 'Teens']::text[], '15 minutes', 'Realizing you were wrong mid-argument produces a flood of defenses: but they also, it was not that bad, I will bring it up later. The page asks for the moment, the defenses the mind offered, the value the client holds about how they want to be in the relationship (honest, repairing, fair), what that value would say right now, and whether they are willing to feel the heat of being wrong and say it. Then the saying, and what happened. Watch for the client who admits fault and then relitigates the other person''s part in the same breath.', '[{"id": "f0", "type": "textarea", "label": "The moment I realized I was wrong, and what we were fighting about:"}, {"id": "f1", "type": "textarea", "label": "The defenses my mind offered, in their exact words:"}, {"id": "f2", "type": "textarea", "label": "The value I hold about how I want to be in this relationship:"}, {"id": "f3", "type": "textarea", "label": "What that value would say out loud, in one or two sentences:"}, {"id": "f4", "type": "textarea", "label": "Am I willing to feel the heat of being wrong and say it anyway? What stops me?"}, {"id": "f5", "type": "textarea", "label": "What I said, when, and what happened in the ten minutes after:"}]'::jsonb, array['relationship issues', 'values', 'repair']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-confronting-the-flaky-friend-grid', 'Pros and Cons of Confronting the Flaky Friend Grid', 'dbt'::resource_kind, 'A pros and cons grid for raising a friend''s repeated cancellations versus letting the friendship drift.', 'Use it to help a client make a deliberate choice about a friendship instead of stewing or ghosting.', array['Adults', 'Teens']::text[], '15 minutes', 'The friend has canceled four times, and the client swings between a confrontation they dread and a quiet fade they will regret. The grid lays out pros and cons of saying something and pros and cons of saying nothing, short term and long term, and then asks which option fits the client''s goals for the friendship and for themselves. It ends with a plan for either path. Watch for the client who chooses silence as the kind option; the grid asks whether it is kind or just easier.', '[{"id": "f0", "type": "textarea", "label": "The pattern, in facts: how many cancellations, over how long, with what reasons:"}, {"id": "f1", "type": "textarea", "label": "Pros and cons of saying something, now and in six months:"}, {"id": "f2", "type": "textarea", "label": "Pros and cons of saying nothing, now and in six months:"}, {"id": "f3", "type": "textarea", "label": "What I want from this friendship, and which option serves that:"}, {"id": "f4", "type": "textarea", "label": "If I speak: the one sentence I will lead with. If I do not: what I will do with the resentment:"}, {"id": "f5", "type": "textarea", "label": "My decision, and the date I will act on it:"}]'::jsonb, array['relationship issues', 'pros and cons', 'friendship']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('checking-each-other-s-phone-trust-talk-sheet-for-partners', 'Checking Each Other''s Phone Trust Talk Sheet for Partners', 'couples'::resource_kind, 'A trust conversation for partners where one checks the other''s phone, or wants to, and both feel watched or doubted.', 'Use it to move a couple from the phone to what each partner is actually afraid of and what would help.', array['Couples']::text[], 'Full session', 'Phone checking is rarely about the phone. The partner who checks is trying to settle a fear, and the partner who is checked feels accused and starts hiding ordinary things, which feeds the fear. The sheet asks the checking partner what the fear is in its own words and where it came from (this relationship or an earlier one), asks the checked partner what being watched does to them, and asks both what would build trust in a way that checking never has. It ends with an agreement about the phones that both can keep. Watch for the pair where there was a real breach; that gets repair work first.', '[{"id": "f0", "type": "textarea", "label": "Partner who checks: the fear in my own words, and where it comes from:"}, {"id": "f1", "type": "textarea", "label": "Partner who checks: what checking gives me for an hour, and what it costs me:"}, {"id": "f2", "type": "textarea", "label": "Partner who is checked: what being watched does to me, and what I have started hiding or hedging:"}, {"id": "f3", "type": "textarea", "label": "Both: what has actually built trust between us in the past:"}, {"id": "f4", "type": "textarea", "label": "Our agreement about the phones for the next month, in plain terms both of us can keep:"}, {"id": "f5", "type": "textarea", "label": "The check-in: when we will talk about how it is going, and what we will each bring:"}]'::jsonb, array['relationship issues', 'couples', 'trust']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('haircut-or-massage-touch-comfort-plan-sheet', 'Haircut or Massage Touch Comfort Plan Sheet', 'worksheet'::resource_kind, 'A comfort plan for appointments where a stranger''s hands are part of the service, written before booking.', 'Use it to give a client choices about touch, position and pacing in ordinary appointments, so they can go or decline on purpose.', array['Adults', 'Teens']::text[], '20 minutes before booking', 'A haircut, a massage, a dental cleaning: for a client with a history of sexual abuse, a stranger''s hands can be unbearable in ways they feel foolish about. The sheet is about choices, not history: which services the client wants, what they can ask for (a chair facing the mirror, a verbal heads-up before touch, keeping a coat on, a pause word), who they could bring, and what they will do if their body says stop halfway. It never asks about what happened. Watch for the client who books the appointment to prove they can and leaves it shaking; the plan is for comfort, not endurance.', '[{"id": "f0", "type": "textarea", "label": "The appointments I want or need, and the ones I have been avoiding:"}, {"id": "f1", "type": "textarea", "label": "What I can ask for before and during: position, a heads-up before touch, what stays on, a pause word:"}, {"id": "f2", "type": "textarea", "label": "Who could come with me or be on the phone in the waiting room:"}, {"id": "f3", "type": "textarea", "label": "What my body does when it has had enough, and what I will say or do when that happens:"}, {"id": "f4", "type": "textarea", "label": "What I will do for myself in the hour after the appointment:"}, {"id": "f5", "type": "textarea", "label": "After: what I asked for, what the provider did, and what I would change next time:"}]'::jsonb, array['sexual abuse', 'safety', 'planning']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('dressing-up-means-asking-for-attention-gentle-check-sheet', 'Dressing Up Means Asking for Attention Gentle Check Sheet', 'cbt'::resource_kind, 'A gentle check of the belief that wearing something the client likes invites what happened to happen again.', 'Use it to examine a self-blaming rule about clothing without pressing the client to change what they wear.', array['Adults', 'Teens']::text[], '20 minutes in session', 'Many survivors carry a rule that what they wear caused or invites harm, and it shrinks the closet to armor. The sheet names the rule in the client''s words, asks where it was learned and who said it, looks at what the rule claims about cause and responsibility, and asks what the client would say to a friend who dressed up for a party. It takes no position on what the client should wear. Done in session, with the clinician watching pace. Watch for the client who hears any challenge to the rule as being told it was not their fault too fast; let them set the speed.', '[{"id": "f0", "type": "textarea", "label": "The rule about clothing, in my own words:"}, {"id": "f1", "type": "textarea", "label": "Where I learned it, and whose voice says it:"}, {"id": "f2", "type": "textarea", "label": "What the rule claims about who is responsible for what:"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend who wore something she loved to a party:"}, {"id": "f4", "type": "textarea", "label": "A sentence about clothes and responsibility that I could try on, even if I only half believe it:"}, {"id": "f5", "type": "textarea", "label": "What I want to wear this month, if the rule were quieter, and whether I want to try one piece of it:"}]'::jsonb, array['sexual abuse', 'self-blame', 'stabilizing']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('values-for-the-friendships-i-choose-now-page', 'Values for the Friendships I Choose Now Page', 'act'::resource_kind, 'A values page for choosing friendships deliberately, for a client whose trust was broken early.', 'Use it to help a client name what they want in a friend and notice the difference between caution and isolation.', array['Adults', 'Teens']::text[], '20 minutes', 'After abuse, friendships can feel either dangerous or compulsory, and a client may keep everyone at arm''s length or keep people who are not good to them. The page asks what the client values in a friend (honesty, patience, respect for a no), who in their life already shows some of that, what caution looks like versus what hiding looks like, and one small step toward a person who passes the values test. It does not ask about who broke the trust. Watch for the client who writes a friend standard no one could meet; ask about the friend who meets half.', '[{"id": "f0", "type": "textarea", "label": "What I value in a friend, in my own words (three to five things):"}, {"id": "f1", "type": "textarea", "label": "People in my life now who show some of those, even in small ways:"}, {"id": "f2", "type": "textarea", "label": "What careful looks like for me, and what hiding looks like; how I tell them apart:"}, {"id": "f3", "type": "textarea", "label": "One small step toward a person who passes my values test, this month:"}, {"id": "f4", "type": "textarea", "label": "What I will do with the fear while I take that step:"}]'::jsonb, array['sexual abuse', 'values', 'connection']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('mindfulness-of-a-safe-object-in-my-pocket-card', 'Mindfulness of a Safe Object in My Pocket Card', 'dbt'::resource_kind, 'A mindfulness card built around one small object the client carries and can hold when the present slips.', 'Use it to give a client a portable anchor they chose, with a practice for using it discreetly in public.', array['Adults', 'Teens']::text[], 'Five minutes daily, then as needed', 'A smooth stone, a key, a ring, a folded note: an object chosen by the client and carried everywhere gives the hand something to do when the mind leaves the room. The card asks the client to pick the object, practice describing it with eyes closed (weight, temperature, edges), and pair it with one sentence about where and when they are. Then it is used in the places that pull them away: a crowded store, a waiting room, a bed at night. It does not ask what pulls them away. Watch for the client who loses the object and spirals; choose a second one together.', '[{"id": "f0", "type": "textarea", "label": "The object I chose, and why this one:"}, {"id": "f1", "type": "textarea", "label": "Describing it with my eyes closed: weight, temperature, texture, edges:"}, {"id": "f2", "type": "textarea", "label": "The sentence I pair with it (''I am in ___, it is ___''):"}, {"id": "f3", "type": "textarea", "label": "The places I will carry it and use it this week:"}, {"id": "f4", "type": "textarea", "label": "After a week: the times I reached for it, and what it did for me:"}]'::jsonb, array['sexual abuse', 'grounding', 'mindfulness']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('no-go-tell-three-step-hopscotch-play', 'No Go Tell Three Step Hopscotch Play', 'kids'::resource_kind, 'A hopscotch play in which a child hops the three steps of body safety: say no, get away, tell a grown-up.', 'Use it to rehearse body safety steps with a young child through movement, with the parent as the grown-up to tell.', array['Children']::text[], '20 minutes', 'Three squares chalked or taped on the floor: NO, GO, TELL. The clinician describes a small pretend situation with a puppet (someone wants to keep a touch a secret, someone will not stop tickling) and the child hops the squares, saying the step out loud on each one and ending by telling the parent, who practices the right answer (I believe you, thank you for telling me). The parent takes a turn hopping too. Keep scenarios simple and age-appropriate. If the child discloses anything, follow your reporting duties and stay calm. Rehearse the parent''s response first.', '[{"id": "f0", "type": "textarea", "label": "My three squares and what I say on each (draw them):"}, {"id": "f1", "type": "textarea", "label": "The pretend situations we practiced:"}, {"id": "f2", "type": "textarea", "label": "What my grown-up said when I told them:"}, {"id": "f3", "type": "textarea", "label": "The grown-ups I could tell in real life (at least three):"}, {"id": "f4", "type": "textarea", "label": "What I will do if the first grown-up does not listen:"}]'::jsonb, array['sexual abuse', 'children', 'safety']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('coping-skills-by-place-car-classroom-office-sort-sheet', 'Coping Skills by Place Car Classroom Office Sort Sheet', 'worksheet'::resource_kind, 'A sorting sheet for which coping skills actually work in the car, at a desk, in a classroom or in a crowd.', 'Use it to help a client match their skills to the places their week actually happens, so none are left with no option.', array['Adults', 'Teens']::text[], '20 minutes', 'A client may know ten skills and still have none for the moment a surge hits in a meeting, because most of their skills need privacy, movement or sound. The sheet lists the places their week happens and sorts every skill they know into each: what can be done while driving, what works silently at a desk, what fits a crowded train. The gaps show where a quiet skill is missing. Watch for the client who has nothing for the places they spend the most time; that is the next skill to teach.', '[{"id": "f0", "type": "textarea", "label": "The places my week actually happens: list them:"}, {"id": "f1", "type": "textarea", "label": "Every coping skill I know, listed:"}, {"id": "f2", "type": "textarea", "label": "For each place: which skills work there without anyone noticing:"}, {"id": "f3", "type": "textarea", "label": "The place with the fewest options, and what a skill for it would need to be (silent, seated, five seconds):"}, {"id": "f4", "type": "textarea", "label": "One skill I will adapt or learn for that place:"}, {"id": "f5", "type": "textarea", "label": "After a week: where I used what, and what still has a gap:"}]'::jsonb, array['coping skills', 'planning', 'regulation']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('if-i-use-a-skill-i-am-avoiding-my-feelings-belief-sheet', 'If I Use a Skill I Am Avoiding My Feelings Belief Sheet', 'cbt'::resource_kind, 'A belief sheet for the worry that using a coping skill is just another way to run from a feeling.', 'Use it to help a client distinguish a skill that makes room for a feeling from one used to escape it.', array['Adults', 'Teens']::text[], '15 minutes', 'Some clients, often ones who have read a lot, worry that breathing or grounding is suppression dressed up. The sheet takes the belief seriously: what the client means by avoiding, what the skill actually does to the feeling (lowers the volume, buys time, or makes it go away), what they do after the skill (turn toward the feeling or change the subject), and a test: use the skill, then sit with the feeling for two minutes. The clinician helps tell the difference. Watch for the client who uses the belief to use no skills at all.', '[{"id": "f0", "type": "textarea", "label": "The belief, in its exact words, and where I picked it up:"}, {"id": "f1", "type": "textarea", "label": "What I mean by avoiding a feeling, with an example from my life:"}, {"id": "f2", "type": "textarea", "label": "What the skill actually does to the feeling when I use it: lowers it, pauses it, erases it:"}, {"id": "f3", "type": "textarea", "label": "What I usually do in the five minutes after using a skill:"}, {"id": "f4", "type": "textarea", "label": "The test: use the skill, then sit with the feeling for two minutes; what happened:"}, {"id": "f5", "type": "textarea", "label": "A sentence about skills and feelings I can live with:"}]'::jsonb, array['coping skills', 'core beliefs', 'avoidance']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('coping-skill-as-training-wheels-page', 'Coping Skill as Training Wheels Page', 'act'::resource_kind, 'A metaphor page for coping skills as training wheels: useful, temporary, and not the point of the ride.', 'Use it to help a client use skills without making the skill the goal or feeling ashamed of needing one.', array['Adults', 'Teens']::text[], '15 minutes', 'Clients get caught two ways with skills: either they are ashamed of needing them or they polish the skill forever and never ride anywhere. Training wheels settle both: nobody is ashamed of them, and nobody keeps them on to admire them. The page asks which skills are the client''s training wheels right now, where they are riding (the value, the life), which wheel might be ready to come off a notch, and which one they still need and can stop apologizing for. Watch for the client who takes all the wheels off at once to prove something.', '[{"id": "f0", "type": "textarea", "label": "The skills I lean on right now, my training wheels:"}, {"id": "f1", "type": "textarea", "label": "Where I am actually riding to: the value or the life the skills are for:"}, {"id": "f2", "type": "textarea", "label": "Which wheel I have been polishing instead of riding, if any:"}, {"id": "f3", "type": "textarea", "label": "Which wheel I could loosen a notch this month, and how I would know it went okay:"}, {"id": "f4", "type": "textarea", "label": "Which wheel I still need, and the sentence I will say to myself instead of an apology for it:"}]'::jsonb, array['coping skills', 'metaphor', 'committed action']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('accepts-sensations-ice-cube-in-the-palm-card', 'ACCEPTS Sensations Ice Cube in the Palm Card', 'dbt'::resource_kind, 'An ACCEPTS card for the Sensations skill, using an ice cube held in the palm during a hard few minutes.', 'Use it to give a client one strong, safe sensation to ride out a spike, with a plan for what comes after.', array['Adults', 'Teens']::text[], 'Five minutes, as needed', 'Of the ACCEPTS skills, Sensations is the one that works when thinking does not: a strong, safe sensation gives the body something present and specific. An ice cube held in the palm is cheap and always available. The card asks the client to describe the sensation as it changes (sharp, aching, numb, melting), to notice what the distress does across those minutes, and to plan the next action when the cube is gone. It is a bridge, not a solution. Watch for the client who holds it long past comfort; set a limit and offer a towel.', '[{"id": "f0", "type": "textarea", "label": "When I will use it: the spikes this fits, and the ones it does not:"}, {"id": "f1", "type": "textarea", "label": "The sensation as it changes, described in plain words across the minutes:"}, {"id": "f2", "type": "textarea", "label": "What the distress did while I held it (0 to 100 at the start, middle and end):"}, {"id": "f3", "type": "textarea", "label": "The next action when the cube is gone, decided before I pick it up:"}, {"id": "f4", "type": "textarea", "label": "After a week: the times I used it, and whether the bridge held:"}]'::jsonb, array['coping skills', 'ACCEPTS', 'distress tolerance']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('coping-skill-speed-dating-rounds-game', 'Coping Skill Speed Dating Rounds Game', 'game'::resource_kind, 'A speed-dating game in which players pitch a coping skill to a partner in two minutes, then rotate.', 'Use it to get a group teaching skills to each other and hearing a skill described five different ways.', array['Groups', 'Teens', 'Adults']::text[], '25 minutes', 'Rules: half the group sits, half rotates. Each seated player has a skill card; in two minutes they pitch it to the person across from them (what it is, when it works, when it does not, a time they used it), and the listener asks one question. Bell, rotate. After five rounds, swap roles with new cards. Debrief: which pitch made you want to try a skill, what you learned about a skill you already use from how someone else described it, and what it was like to be the expert for two minutes. Watch for the member who pitches a skill they have never used; that is allowed, and worth naming.', '[{"id": "f0", "type": "textarea", "label": "The skill I pitched, and how my pitch changed by the fifth round:"}, {"id": "f1", "type": "textarea", "label": "The pitch that made me want to try something, and why:"}, {"id": "f2", "type": "textarea", "label": "Something I learned about a skill I already use from how someone else described it:"}, {"id": "f3", "type": "textarea", "label": "The question I was asked that I could not answer:"}, {"id": "f4", "type": "textarea", "label": "What it was like to be the expert for two minutes:"}]'::jsonb, array['coping skills', 'group', 'game']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('getting-in-the-back-seat-of-a-rideshare-step-plan-sheet', 'Getting in the Back Seat of a Rideshare Step Plan Sheet', 'worksheet'::resource_kind, 'A step plan for a client who avoids rideshares and taxis because a stranger is driving and the doors are not theirs.', 'Use it to build a ladder from looking at the app to a short ride, with the client in charge of each rung.', array['Adults', 'Teens']::text[], '20 minutes to plan, then the steps', 'A rideshare asks the client to sit behind a stranger, in a car they do not control, for a route they did not pick, and many clients would rather walk in the rain. The sheet builds the ladder: open the app and look, book and cancel, a five-minute ride with a friend, a ride alone in daylight, a ride alone at night. Each rung has a prediction and a result. The client chooses what they can do in the car (a window cracked, a text to a friend, the route on their own phone). Watch for the client who does the top rung first to get it over with and never does another.', '[{"id": "f0", "type": "textarea", "label": "What I avoid, and what it has cost me this year (missed events, long walks, money):"}, {"id": "f1", "type": "textarea", "label": "My ladder, from easiest to hardest, five rungs:"}, {"id": "f2", "type": "textarea", "label": "What I will allow myself in the car (a window, a text, the route on my own phone):"}, {"id": "f3", "type": "textarea", "label": "Rung one: my prediction, what happened, and what I felt from start to finish:"}, {"id": "f4", "type": "textarea", "label": "Each next rung: the same:"}, {"id": "f5", "type": "textarea", "label": "What I notice about the predictions as I climb:"}]'::jsonb, array['phobias', 'hierarchy', 'exposure']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('the-bee-will-sting-me-if-i-stay-still-prediction-sheet', 'The Bee Will Sting Me If I Stay Still Prediction Sheet', 'cbt'::resource_kind, 'A prediction sheet for the belief that a bee nearby will sting unless the client runs or swats.', 'Use it to test the client''s forecast against what bees actually do when a person stays still, in a planned observation.', array['Adults', 'Teens', 'Children']::text[], '15 minutes, then one observation', 'The client''s forecast is specific: if I do not move, it will sting me. The forecast has never been tested because the client always moves. The sheet records the prediction and its certainty, what the client knows about why bees sting (defense, being trapped or swatted), and sets a planned observation from a safe distance: watch a bee at a flower for one minute without moving away, record what it did. A client with a bee allergy does this only in imagination or from indoors. Watch for the child who wants to prove bravery by getting close; distance is part of the plan.', '[{"id": "f0", "type": "textarea", "label": "My prediction when a bee is near and I stay still, and how sure I am (0 to 100):"}, {"id": "f1", "type": "textarea", "label": "What I know about why bees sting people:"}, {"id": "f2", "type": "textarea", "label": "The observation plan: where, how far away, for how long, with whom:"}, {"id": "f3", "type": "textarea", "label": "What the bee actually did for the minute I watched:"}, {"id": "f4", "type": "textarea", "label": "My certainty now, and what changed it or did not:"}, {"id": "f5", "type": "textarea", "label": "The next observation, a little closer or a little longer, if I am willing:"}]'::jsonb, array['phobias', 'predictions', 'behavioral experiment']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('willing-to-step-onto-the-boat-dock-page', 'Willing to Step Onto the Boat Dock Page', 'act'::resource_kind, 'A willingness page for deep water and unsteady ground: the dock, the pier, the edge of the lake.', 'Use it to help a client carry the fear of water to the edge of it, in service of a value, one step at a time.', array['Adults', 'Teens']::text[], '15 minutes, then one visit', 'The client''s family goes to the lake and the client stays on the grass, because the dock sways and the water is dark. The page asks what being at the water would make possible (watching the kids swim, a boat ride with a partner), the value under it, what the fear says the moment a foot touches the dock, and whether the client is willing to feel the sway in their stomach for one minute on the first board. Then the first board. Watch for the client who wants the fear gone before they step; the step is with the fear.', '[{"id": "f0", "type": "textarea", "label": "What the water keeps me from, and who is out there without me:"}, {"id": "f1", "type": "textarea", "label": "The value under wanting to be there, in my own words:"}, {"id": "f2", "type": "textarea", "label": "What the fear says and what my body does the moment a foot touches the dock:"}, {"id": "f3", "type": "textarea", "label": "Am I willing to feel that for one minute on the first board? What would willing look like in my feet and my breath?"}, {"id": "f4", "type": "textarea", "label": "The visit: how far I went, how long I stayed, and what the fear did while I stood there:"}]'::jsonb, array['phobias', 'willingness', 'values']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('cope-ahead-imagery-for-the-costume-mascot-card', 'Cope Ahead Imagery for the Costume Mascot Card', 'dbt'::resource_kind, 'A cope-ahead card for a client who dreads people in costumes and mascots at games, parks and parties.', 'Use it to rehearse an encounter with a costumed character in imagination, skills included, before the event.', array['Adults', 'Teens', 'Children']::text[], '15 minutes before the event', 'Fear of people in costumes is real and rarely taken seriously, which leaves the client alone with it at every ballgame and birthday party. The card walks cope ahead: the event, where the mascot is likely to be, the emotion and its intensity, the skills (paced breathing, a fixed spot to look at, a plan for distance, a companion''s arm), a vivid rehearsal in the present tense, and the plan for leaving the area if needed without leaving the event. Watch for the client who rehearses the mascot approaching them; rehearse the coping, not the chase.', '[{"id": "f0", "type": "textarea", "label": "The event, and where a costumed character is likely to appear:"}, {"id": "f1", "type": "textarea", "label": "The emotion I expect and its intensity (0 to 100):"}, {"id": "f2", "type": "textarea", "label": "The skills I will use, named: breath, where I look, how much distance, who is with me:"}, {"id": "f3", "type": "textarea", "label": "My rehearsal in the present tense: I see the mascot across the field, and I...:"}, {"id": "f4", "type": "textarea", "label": "My plan for stepping away from the area without leaving the event:"}, {"id": "f5", "type": "textarea", "label": "After: what happened, and how the imagined version compared:"}]'::jsonb, array['phobias', 'cope ahead', 'core DBT']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('brave-puppy-meets-the-hair-dryer-play', 'Brave Puppy Meets the Hair Dryer Play', 'kids'::resource_kind, 'A puppet play in which a stuffed puppy learns to be near a loud appliance, with the child as the trainer.', 'Use it to let a child rehearse approaching a feared noise by coaching a toy through it first, with the parent running the dryer.', array['Children']::text[], '20 minutes', 'A child who is afraid of the hair dryer, the vacuum or the blender gets to be the brave one by training a puppy. The child holds a stuffed dog, the parent holds the dryer (off at first, then on low in another room, then closer), and the child coaches the puppy through each step: ''Okay, puppy, it is loud but it is just air, let''s take a breath.'' The child decides when the puppy is ready for the next step. Watch for the parent who rushes the steps; the child is the trainer, and the puppy moves at the child''s pace.', '[{"id": "f0", "type": "textarea", "label": "My puppy''s name, and what it is scared of:"}, {"id": "f1", "type": "textarea", "label": "The steps we did: off, far away on low, closer, and how far we got:"}, {"id": "f2", "type": "textarea", "label": "What I said to my puppy when it got scared:"}, {"id": "f3", "type": "textarea", "label": "What my grown-up did to help:"}, {"id": "f4", "type": "textarea", "label": "The next step my puppy is ready for:"}]'::jsonb, array['phobias', 'children', 'play']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('group-costume-or-matching-shirts-event-decision-sheet', 'Group Costume or Matching Shirts Event Decision Sheet', 'worksheet'::resource_kind, 'A decision sheet for the team event that requires a matching outfit, when the outfit is why the client wants to skip.', 'Use it to separate the outfit from the event and to help the client decide what they want to do, with options between all and nothing.', array['Adults', 'Teens']::text[], '15 minutes', 'A matching team shirt or a group costume strips the client of the clothes they usually hide in, and skipping the event feels easier than being seen. The sheet asks what the event itself offers (the people, the fun, the belonging), what the outfit thought says, the options between skipping and wearing exactly what everyone wears (a layer over it, a different cut, arriving late), and what the client will do with the thoughts if they go. It never discusses the body itself. Watch for the client who decides the outfit is the real problem; the decision is about the event.', '[{"id": "f0", "type": "textarea", "label": "The event, and what it offers me apart from the clothes:"}, {"id": "f1", "type": "textarea", "label": "The thought about the outfit, in its exact words:"}, {"id": "f2", "type": "textarea", "label": "Options between skipping and wearing exactly what everyone wears:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the thoughts if I go (a plan for the first ten minutes):"}, {"id": "f4", "type": "textarea", "label": "My decision, and what I would tell a friend who was deciding the same thing:"}, {"id": "f5", "type": "textarea", "label": "After: what I did, what I noticed about who was looking, and whether I was glad I went:"}]'::jsonb, array['body image', 'decisions', 'avoidance']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('looking-old-in-the-video-call-thought-record', 'Looking Old in the Video Call Thought Record', 'cbt'::resource_kind, 'A thought record for the client who sees their own face on a video call and loses the meeting to it.', 'Use it to catch appearance thoughts that hijack attention at work and to test what other people on the call actually attend to.', array['Adults']::text[], '15 minutes', 'The call starts, the client''s own face appears in the corner, and for the next hour they watch themselves age instead of hearing the meeting. The record asks for the thought, what it did to attention, the evidence that others are studying the client''s face (how much the client studies anyone else''s), and a small experiment: hide self-view for one call and note what happens to the thoughts and to the meeting. It never asks the client to describe their face. Watch for the client who checks their appearance before every call as prevention; that goes on the sheet.', '[{"id": "f0", "type": "textarea", "label": "The thought when my face appeared on screen, in its exact words:"}, {"id": "f1", "type": "textarea", "label": "What it did to my attention during the call, honestly:"}, {"id": "f2", "type": "textarea", "label": "How much I study other people''s faces on a call, and what that suggests about them studying mine:"}, {"id": "f3", "type": "textarea", "label": "The experiment: hide self-view for one call; what happened to the thoughts and to the meeting:"}, {"id": "f4", "type": "textarea", "label": "What I do before calls to prepare my appearance, and how long it takes:"}, {"id": "f5", "type": "textarea", "label": "A sentence about my face on a call that is accurate and lets me hear the meeting:"}]'::jsonb, array['body image', 'thought record', 'attention']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('body-as-the-instrument-not-the-performance-page', 'Body as the Instrument Not the Performance Page', 'act'::resource_kind, 'A values metaphor for the body as the instrument the client plays their life on, not the show itself.', 'Use it to move a client''s attention from how the body looks to what it lets them do and who they are through it.', array['Adults', 'Teens']::text[], '20 minutes', 'Nobody judges a cello by its finish while the music plays. The page asks the client what they play on their body (the walks, the work, the holding of children, the laughing), what the audience in their head keeps reviewing instead, the value the playing serves, and one act this week that uses the instrument for its purpose while the review runs. It says nothing about how the body looks and asks nothing about it. Watch for the client who turns the instrument into something to maintain perfectly; that is the old performance in new clothes.', '[{"id": "f0", "type": "textarea", "label": "What I play on this body: the things it lets me do and the people it lets me hold:"}, {"id": "f1", "type": "textarea", "label": "What the reviewer in my head keeps rating instead:"}, {"id": "f2", "type": "textarea", "label": "The value the playing serves, in my own words:"}, {"id": "f3", "type": "textarea", "label": "One thing I will do this week that uses the instrument for its purpose while the review runs:"}, {"id": "f4", "type": "textarea", "label": "After: what the body did, what the reviewer said, and which one I listened to:"}]'::jsonb, array['body image', 'values', 'metaphor']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('half-smile-walking-past-the-reflective-storefront-card', 'Half Smile Walking Past the Reflective Storefront Card', 'dbt'::resource_kind, 'A half-smile card for the glass storefront the client checks or avoids on the daily route.', 'Use it to practice a softened face and a steady pace past a reflection, instead of a check or a detour.', array['Adults', 'Teens']::text[], 'Daily on the route', 'Every route has a window that doubles as a mirror, and the client either checks in it or crosses the street. Half smile, the slight softening of the face that the body reads as acceptance, paired with willing hands and a steady pace, gives a third option: walk past, face soft, eyes ahead or on the display, reflection unchecked. The card asks the client to name the window, practice the half smile at home, and log the walks past. It does not ask what they see in the glass. Watch for the client who uses the half smile to check the smile; eyes on the display.', '[{"id": "f0", "type": "textarea", "label": "The window on my route, and what I usually do when I pass it:"}, {"id": "f1", "type": "textarea", "label": "Practicing the half smile at home: what my face and jaw do, and what shifts inside:"}, {"id": "f2", "type": "textarea", "label": "What I will look at as I pass, instead of the glass:"}, {"id": "f3", "type": "textarea", "label": "Daily log: passed with a half smile and a steady pace, checked, or crossed the street:"}, {"id": "f4", "type": "textarea", "label": "After two weeks: what has changed about that stretch of sidewalk:"}]'::jsonb, array['body image', 'half smile', 'mindfulness']::text[], '2026-11-23T15:00:00+00:00'::timestamptz),
  ('beach-or-lake-trip-comfort-plan-for-partners', 'Beach or Lake Trip Comfort Plan for Partners', 'couples'::resource_kind, 'A plan for a trip to the water, where one partner dreads being seen and the other does not know how to help.', 'Use it to turn a loaded trip into a shared plan both partners wrote, with no commentary on anyone''s body.', array['Couples']::text[], '20 minutes before the trip', 'A day at the beach is a holiday for one partner and an ordeal for the other, who skips it or spends it wrapped up and silent. The plan asks the uncomfortable partner what would make the day easier (a spot away from the crowd, shade, a cover-up with no comment, getting into the water unwatched), and asks the other what they will do and not do (no compliments about looks, no urging to take anything off, a hand to hold on the way in). It never mentions the body itself. Watch for the partner who promises no comments and then says ''you look great''; that is a comment.', '[{"id": "f0", "type": "textarea", "label": "Uncomfortable partner: what would make the day easier, specifically (place, shade, timing, cover):"}, {"id": "f1", "type": "textarea", "label": "Uncomfortable partner: what I need my partner to not say or do, even kindly:"}, {"id": "f2", "type": "textarea", "label": "Other partner: what I will do to make the day good for both of us:"}, {"id": "f3", "type": "textarea", "label": "Other partner: what I will do with my own disappointment if the day is quieter than I hoped:"}, {"id": "f4", "type": "textarea", "label": "Our plan for the hour we arrive, and the signal for ''I need a minute'':"}, {"id": "f5", "type": "textarea", "label": "After the trip: what worked, and what we would change next time:"}]'::jsonb, array['body image', 'couples', 'support']::text[], '2026-11-23T15:00:00+00:00'::timestamptz)
